window.QCM_DATA = [

/* ---- Ch. 1 : le triple cadre ---- */
{id:"A01", ch:1, d:1, q:"Quels sont les <b>trois cadres</b> dans lesquels s'inscrit l'intégration de la SSI&nbsp;?", o:["Réglementaire et légal · normatif · méthodologique","Technique · organisationnel · humain","Préventif · détectif · correctif","Stratégique · tactique · opérationnel"], a:[0], e:"Le <b>cadre réglementaire</b> impose, le <b>cadre normatif</b> propose un référentiel de consensus, le <b>cadre méthodologique</b> guide la mise en œuvre en s'appuyant sur l'expérience des sachants et l'organisation d'ateliers."},
{id:"A02", ch:1, d:2, q:"Quelle est la différence de nature entre une <b>obligation</b> et une <b>norme</b>&nbsp;?", o:["L'obligation est par définition externe à l'entreprise ; la norme peut être interne ou externe","L'obligation est technique, la norme est juridique","L'obligation est facultative, la norme est contraignante","Il n'y a pas de différence : les deux s'imposent de la même façon"], a:[0], e:"Les exigences se déclinent en <b>légales et réglementaires</b>, et sont toutes externes. Les normes, elles, se déclinent en <b>normes internes et externes</b>. Et attention : il arrive qu'une <b>norme dicte la réglementation</b> et devienne elle-même un support réglementaire."},
{id:"A03", ch:1, d:1, q:"Dans quelle colonne ranger le <b>RGPD</b>&nbsp;?", o:["Obligation","Norme","Méthode","Outil"], a:[0], e:"Avec le <b>Cybersecurity Act</b>, la <b>directive NIS</b> et l'instruction interministérielle sur la protection contre les <b>SPC</b> (signaux parasites compromettants)."},
{id:"A04", ch:1, d:2, q:"Où ranger <b>ITIL</b>, <b>DevOps</b> et le <b>NIST Cybersecurity Framework</b>&nbsp;?", o:["Ce sont des méthodes","Ce sont des normes","Ce sont des obligations","Ce sont des outils"], a:[0], e:"Avec <b>CTL</b> (CyberThreat Landscape) et <b>GISSIP</b> (sécurité dans les projets). Une méthode est un <b>guide de bonnes pratiques</b> ; elle ne se confond pas avec l'outil qui la supporte."},
{id:"A05", ch:1, d:2, q:"Le support insiste&nbsp;: il ne faut pas confondre la méthode et…", o:["l'outil qui supporte son application — par exemple la méthode DevOps et les outils Git ou Jenkins","la norme correspondante","l'obligation réglementaire","le référentiel d'audit"], a:[0], e:"Le même piège vaut pour la <b>méthode EBIOS RM</b> et l'outil <b>Agile Risk Manager</b> utilisé pendant la journée 3."},
{id:"A06", ch:1, d:2, q:"Pour le <b>risque IA</b>, quelle est l'obligation, quelle est la norme&nbsp;?", o:["Obligation : l'AI Act européen · Norme : ISO/IEC 42001 (AIMS), complétée par ISO/IEC 23894","Obligation : ISO 42001 · Norme : l'AI Act","Obligation : le RGPD · Norme : ISO 27005","Obligation : NIS 2 · Norme : ISO 27001"], a:[0], e:"Côté méthode, «&nbsp;il n'existe pas une mais <b>plusieurs</b> méthodes&nbsp;» : <b>NIST AI RMF</b>, <b>EBIOS RM</b>, méthodes internes. Elles traitent les <b>trois types de risque IA</b> : <b>adversarial</b>, <b>intrinsèque</b>, <b>d'impact</b>."},
{id:"A07", ch:1, d:3, q:"Que sont les <b>SI de classe C3</b>, cités comme exemple d'obligation en analyse de risque&nbsp;?", o:["Des SI relevant des risques industriels critiques, dont la conformité est vérifiée par l'autorité étatique ou un organisme accrédité","Des SI classifiés défense","Des SI hébergeant des données personnelles","Des SI certifiés ISO 27001 niveau 3"], a:[0], e:"Dans le domaine de la défense, ces SI sont <b>tenus de disposer d'une analyse de risque</b>. Les obligations y sont plus fortes et la conformité est <b>vérifiée</b>, pas simplement déclarée."},
{id:"A08", ch:1, d:1, q:"Quelles sont les <b>cinq questions</b> à poser pour évaluer le niveau de sécurité attendu&nbsp;?", o:["Que protéger ? de quoi se protéger ? à quels risques suis-je exposé ? qu'est-ce que je redoute ? quelles normes s'appliquent ?","Qui, quoi, où, quand, comment ?","Quel budget ? quel délai ? quelle équipe ? quel outil ? quel périmètre ?","Quelle menace ? quelle vulnérabilité ? quel impact ? quelle probabilité ? quel coût ?"], a:[0], e:"Les mesures «&nbsp;dépendent de l'<b>activité</b>, de l'<b>organisation</b>, de la <b>réglementation</b> et des <b>contraintes de l'écosystème</b>&nbsp;». Pour y répondre, on s'appuie sur l'<b>ISO 27000</b>, les guides <b>ANSSI</b> et <b>CLUSIF</b>, voire la <b>PSSIE</b> et le <b>RGS</b>."},

/* ---- Ch. 2 : la norme ---- */
{id:"A09", ch:2, d:1, q:"Selon la définition ISO/CEI, une norme est un document établi par…", o:["consensus et approuvé par un organisme reconnu","décision d'une autorité réglementaire","vote majoritaire des industriels du secteur","un comité d'experts indépendants"], a:[0], e:"«&nbsp;…qui fournit, pour des <b>usages communs et répétés</b>, des règles, des lignes directrices ou des caractéristiques, garantissant un <b>niveau d'ordre optimal dans un contexte donné</b>.&nbsp;»"},
{id:"A10", ch:2, d:2, q:"Quelles sont les <b>deux conditions</b> pour qu'un document soit considéré comme une norme&nbsp;?", o:["Les moyens décrits doivent être reproductibles, et faire l'objet d'un consensus","Être publié par l'ISO et traduit en français","Être gratuit et accessible en ligne","Être révisé tous les cinq ans et audité"], a:[0], e:"Reproductibles «&nbsp;en utilisant et respectant les conditions indiquées&nbsp;», et le consensus signifie «&nbsp;<b>recevoir la reconnaissance de tous</b>&nbsp;». C'est ce qui en fait un <b>référentiel incontestable commun</b>, utilisé pour <b>simplifier les relations contractuelles</b>."},
{id:"A11", ch:2, d:2, q:"Pourquoi une norme est-elle nécessairement en retard sur la technique&nbsp;?", o:["Parce qu'elle indique l'état de la science, de la technologie et des savoir-faire au moment de sa rédaction","Parce que les comités de normalisation sont lents","Parce qu'elle doit être traduite dans toutes les langues","Parce qu'elle attend la jurisprudence"], a:[0], e:"C'est la raison structurelle pour laquelle «&nbsp;la conformité à une norme <b>ne garantit pas formellement un niveau de sécurité</b>&nbsp;» : les normes <b>ne prennent pas en compte l'état de l'art récent</b>. Le principe de <b>pertinence</b> impose d'ailleurs de les réviser régulièrement, sinon de les maintenir ou de les annuler."},
{id:"A12", ch:2, d:3, q:"Parmi les <b>sept principes de la normalisation</b>, lequel garantit qu'on n'aboutira pas à des <b>normes contradictoires</b>&nbsp;?", o:["La cohérence : les travaux sont coordonnés et centralisés","L'impartialité","Le consensus","La transparence"], a:[0], e:"Les sept sont : <b>transparence</b>, <b>ouverture</b>, <b>impartialité</b>, <b>consensus</b>, <b>efficacité</b>, <b>pertinence</b>, <b>cohérence</b>."},
{id:"A13", ch:2, d:2, q:"Que signifie le principe d'<b>efficacité</b> dans le processus de normalisation&nbsp;?", o:["Les normes sont définies sur la base de l'aptitude à l'emploi plutôt que de caractéristiques descriptives","Les normes doivent être rédigées rapidement","Les normes doivent réduire les coûts de production","Les normes doivent être applicables sans formation"], a:[0], e:"À distinguer de la <b>pertinence</b>, qui porte sur la <b>révision régulière</b> pour rester conforme à l'état de l'art."},

/* ---- Ch. 3 : NIS et NIS 2 ---- */
{id:"A14", ch:3, d:1, q:"De quand datent respectivement la directive <b>NIS</b> et la directive <b>NIS 2</b>&nbsp;?", o:["NIS : 2016 · NIS 2 : 2022","NIS : 2018 · NIS 2 : 2023","NIS : 2019 · NIS 2 : 2024","NIS : 2016 · NIS 2 : 2019"], a:[0], e:"NIS (2016/1148) est la <b>première législation européenne</b> sur la cybersécurité. NIS 2 (2022/2555) la <b>remplace et l'abroge</b>."},
{id:"A15", ch:3, d:2, q:"Quelles étaient les <b>deux catégories</b> d'entités visées par la directive NIS de 2016&nbsp;?", o:["Les opérateurs de services essentiels (OSE) et les fournisseurs de services numériques (FSN)","Les entités essentielles et les entités importantes","Les OIV et les OSE","Les administrations et les entreprises privées"], a:[0], e:"<b>OSE</b> : énergie, transport, santé, infrastructures numériques. <b>FSN</b> : cloud, moteurs de recherche, places de marché en ligne. La distinction <b>essentielles / importantes</b> est une nouveauté de <b>NIS 2</b>."},
{id:"A16", ch:3, d:3, q:"Entre entités <b>essentielles</b> et <b>importantes</b> au sens de NIS 2, qu'est-ce qui est <b>identique</b>&nbsp;?", o:["Les obligations de cybersécurité : gestion des risques, gouvernance, notification d'incidents","Le niveau de sanctions","Le mode de supervision","Rien : tout diffère"], a:[0], e:"C'est le piège classique. Ce qui <b>diffère</b> : la <b>supervision</b> — <b>proactive</b> avec contrôles réguliers pour les essentielles, <b>réactive</b> et déclenchée par un incident pour les importantes — et le <b>niveau de sanctions</b>."},
{id:"A17", ch:3, d:2, q:"Quels <b>délais de notification</b> NIS 2 impose-t-elle&nbsp;?", o:["24 h pour l'alerte précoce, 72 h pour le rapport complet","24 h pour le rapport complet uniquement","48 h puis 96 h","Aucun délai précis : c'est laissé aux États membres"], a:[0], e:"C'est justement l'une des différences majeures avec NIS : la directive de 2016 imposait une obligation de notifier <b>sans délais précis</b>."},
{id:"A18", ch:3, d:2, q:"Quels <b>nouveaux secteurs</b> NIS 2 fait-elle entrer dans son champ&nbsp;?", o:["Administration publique, gestion des déchets, spatial, production alimentaire","Banque, assurance, télécommunications","Défense et renseignement","Éducation et recherche"], a:[0], e:"Le champ est <b>élargi</b> par rapport aux OSE et FSN de 2016, et la directive introduit la <b>responsabilité des dirigeants</b> ainsi que des exigences sur la <b>supply chain</b> et les <b>tests de sécurité</b>."},
{id:"A19", ch:3, d:1, q:"Dans quelle catégorie NIS 2 range-t-elle les <b>services postaux</b> et la <b>gestion des déchets</b>&nbsp;?", o:["Entités importantes","Entités essentielles","Ni l'une ni l'autre : ils sont hors champ","Cela dépend de leur taille uniquement"], a:[0], e:"Avec la <b>production alimentaire</b> et la <b>fabrication</b> (produits médicaux, chimiques, électroniques, machines). Les <b>essentielles</b> sont énergie, transport, santé, <b>eau potable</b>, infrastructures numériques, administration publique, spatial."},

/* ---- Ch. 4 : Cybersecurity Act ---- */
{id:"A20", ch:4, d:1, q:"Le <b>Cybersecurity Act</b> est…", o:["un règlement européen de 2019, d'application directe","une directive de 2019, à transposer","une norme ISO","une recommandation de l'ENISA"], a:[0], e:"C'est LA différence de nature avec NIS 2, qui est une <b>directive</b> devant être <b>transposée dans le droit national</b>."},
{id:"A21", ch:4, d:2, q:"Qu'est-ce que le Cybersecurity Act change pour l'<b>ENISA</b>&nbsp;?", o:["Il lui donne un mandat permanent — elle était jusque-là une agence temporaire","Il la dissout au profit des CSIRT nationaux","Il lui confie le pouvoir de sanction","Il la transforme en organisme de normalisation"], a:[0], e:"Avec le soutien aux États membres et la <b>coordination en cas de crise</b>. Le CSA lui confie aussi la <b>gestion des schémas de certification européens</b>."},
{id:"A22", ch:4, d:1, q:"Quels sont les <b>trois niveaux d'assurance</b> du cadre européen de certification&nbsp;?", o:["Basique · substantiel · élevé","Faible · moyen · fort","Bronze · argent · or","Niveau 1 · niveau 2 · niveau 3"], a:[0], e:"<b>Basique</b> : menaces courantes, conformité minimale. <b>Substantiel</b> : menaces plus sophistiquées. <b>Élevé</b> : niveau maximal de confiance, exigences strictes de vérification et d'évaluation."},
{id:"A23", ch:4, d:3, q:"Le Cybersecurity Act prévoit-il des <b>sanctions</b>&nbsp;?", o:["Non : pas de sanctions directes, mais une obligation de reconnaître les certifications dans l'UE","Oui, des amendes administratives comme NIS 2","Oui, mais uniquement pour les fournisseurs non européens","Oui, le retrait de la certification"], a:[0], e:"C'est une différence structurelle : <b>NIS 2 protège des entités et sanctionne</b> ; le <b>Cybersecurity Act certifie des produits et fait reconnaître</b>."},
{id:"A24", ch:4, d:2, q:"Qui est concerné par le Cybersecurity Act&nbsp;?", o:["Tous les produits, services et processus TIC pouvant être certifiés — fabricants, prestataires, fournisseurs TIC","Uniquement les opérateurs d'importance vitale","Uniquement les administrations publiques","Les mêmes entités que NIS 2"], a:[0], e:"Là où NIS 2 vise des <b>secteurs</b> et des <b>entités</b> (essentielles et importantes), le CSA vise des <b>produits</b> et leurs fournisseurs."},

/* ---- Ch. 5 : ISO 27k ---- */
{id:"A25", ch:5, d:1, q:"À quoi sert la suite <b>ISO/CEI 27000</b>&nbsp;?", o:["Fournir des recommandations de meilleures pratiques en management de la sécurité de l'information, pour initialiser, implémenter ou maintenir un SMSI","Certifier les produits de sécurité","Définir les obligations légales européennes","Normaliser les protocoles de chiffrement"], a:[0], e:"<b>SMSI</b> = système de management de la sécurité de l'information."},
{id:"A26", ch:5, d:2, q:"Associez correctement&nbsp;: quelle norme définit les <b>lignes directrices de gestion des risques</b>&nbsp;?", o:["ISO 27005","ISO 27001","ISO 27002","ISO 27035"], a:[0], e:"<b>27001</b> = le SMSI (certifiable) · <b>27002</b> = les bonnes pratiques · <b>27004</b> = les mesures/indicateurs · <b>27005</b> = la gestion des risques · <b>27035</b> = la gestion des incidents · <b>27037</b> = le traitement des preuves numériques."},
{id:"A27", ch:5, d:2, q:"Quelle norme traite du <b>traitement des preuves numériques</b> (forensics)&nbsp;?", o:["ISO 27037","ISO 27035","ISO 27005","ISO 27034"], a:[0], e:"Ne pas la confondre avec <b>27035</b>, qui traite de la <b>gestion des incidents</b>. <b>27034</b>, elle, porte sur la <b>sécurité applicative</b>."},
{id:"A28", ch:5, d:3, q:"Pourquoi la conformité à une norme ne garantit-elle pas un niveau de sécurité&nbsp;?", o:["Parce que les normes ne prennent en compte ni l'état de l'art récent ni les exigences réglementaires","Parce que les audits sont déclaratifs","Parce que les normes sont payantes","Parce qu'elles ne sont pas opposables juridiquement"], a:[0], e:"L'avertissement figure deux fois dans le support, et c'est le pendant de la limite de l'ISO 27001, qui <b>n'impose aucun niveau minimum</b>."},

/* ---- Ch. 6 : ISO 27001 ---- */
{id:"A29", ch:6, d:1, q:"Sur quel cycle la norme <b>ISO 27001</b> est-elle calquée&nbsp;?", o:["Le Plan / Do / Check / Act de la norme ISO 9000","Le cycle de Deming inversé","Le cycle du renseignement","Le cycle de vie du développement logiciel"], a:[0], e:"La phase <b>Plan</b> est la plus détaillée par le support : <b>identification des actifs</b>, <b>analyse de risques</b>, puis <b>choix du périmètre du SMSI</b>."},
{id:"A30", ch:6, d:2, q:"Quelle est la <b>durée de validité</b> d'une certification ISO 27001, et quel contrôle intervient entre-temps&nbsp;?", o:["3 ans, avec un audit de contrôle tous les ans","5 ans, sans contrôle intermédiaire","1 an renouvelable","3 ans, avec un audit à mi-parcours"], a:[0], e:"La certification «&nbsp;garantit qu'une organisation a bien appliqué les <b>exigences de la norme</b>&nbsp;» — pas qu'elle atteint un niveau de sécurité donné."},
{id:"A31", ch:6, d:3, q:"Quelle est la <b>limite majeure</b> de la certification ISO 27001&nbsp;?", o:["La norme n'impose aucun niveau minimum de sécurité : on peut être certifié avec un périmètre réduit et une politique peu stricte","Elle n'est pas reconnue en Europe","Elle ne couvre pas les données personnelles","Elle expire au bout d'un an"], a:[0], e:"C'est écrit noir sur blanc dans le support. La certification atteste d'une <b>démarche</b>, pas d'un <b>résultat</b> — d'où l'importance du choix du <b>périmètre</b> en phase <i>Plan</i>."},
{id:"A32", ch:6, d:2, q:"Dans la phase <b>Plan</b>, le choix du périmètre du SMSI se décompose en trois questions. Lesquelles&nbsp;?", o:["Quel périmètre de sécurité ? quelle politique de sécurité ? quel niveau de sécurité ?","Quel budget ? quel délai ? quelle équipe ?","Quels actifs ? quelles menaces ? quels impacts ?","Qui décide ? qui exécute ? qui contrôle ?"], a:[0], e:"Elles arrivent après l'<b>identification des actifs ou des biens</b> et l'<b>analyse de risques</b>."},

/* ---- Ch. 7 : ISO 27002 ---- */
{id:"A33", ch:7, d:1, q:"Combien de mesures compte l'<b>ISO 27002:2022</b>, et combien en comptait la version 2013&nbsp;?", o:["93 en 2022, contre 114 en 2013","114 en 2022, contre 93 en 2013","93 en 2022, contre 133 en 2013","100 en 2022, contre 120 en 2013"], a:[0], e:"Et le nombre de <b>thèmes</b> passe de <b>14 à 4</b>. La refonte embarque <b>11 nouvelles mesures</b>."},
{id:"A34", ch:7, d:2, q:"Quels sont les <b>quatre thèmes</b> de l'ISO 27002:2022, et leur pondération&nbsp;?", o:["Organisationnelles (37) · personnes (8) · physiques (14) · technologiques (34)","Organisationnelles (34) · personnes (14) · physiques (8) · technologiques (37)","Prévention (37) · détection (8) · correction (14) · récupération (34)","Gouvernance (37) · protection (8) · défense (14) · résilience (34)"], a:[0], e:"37 + 8 + 14 + 34 = <b>93</b>. Le thème <b>organisationnel</b> pèse à lui seul <b>40&nbsp;%</b> des mesures : la sécurité de l'information est d'abord une affaire d'organisation."},
{id:"A35", ch:7, d:2, q:"Quelle nouveauté l'ISO 27002:2022 introduit-elle sous forme de <b>#hashtag</b>&nbsp;?", o:["La notion de propriété (attribute), qui permet de filtrer les mesures selon plusieurs axes","Un système de notation des mesures","Une classification par secteur d'activité","Un lien automatique vers les exigences de l'ISO 27001"], a:[0], e:"Cinq familles d'attributs : <b>types de contrôles</b> (#Prévention, #Détection, #Correction) · <b>propriétés de sécurité</b> (#Confidentialité, #Intégrité, #Disponibilité) · <b>concepts</b> (#Identification, #Protection, #Traitement, #Détection, #Récupération) · <b>capacités opérationnelles</b> · <b>domaines de sécurité</b> (#Gouvernance_et_écosystème, #Protection, #Défense, #Résilience)."},
{id:"A36", ch:7, d:3, q:"Quelles mesures figurent parmi les <b>11 nouvelles</b> de la version 2022&nbsp;?", o:["L'intelligence de la menace","La suppression de l'information","L'anonymisation","La sécurité dans le développement","La sécurité du câblage"], a:[0,1,2,3], e:"Toutes les quatre sont citées explicitement par le support. Elles reflètent l'évolution du contexte : <b>CTI</b>, <b>RGPD</b> (droit à l'effacement), <b>protection des données</b>, <b>DevSecOps</b>."},
{id:"A37", ch:7, d:2, q:"Dans quelle série de l'ISO 27002:2022 se range la mesure <b>« Travail à distance »</b>&nbsp;?", o:["06.xx — mesures liées aux personnes","05.xx — organisationnelles","07.xx — physiques","08.xx — technologiques"], a:[0], e:"La série <b>06</b> ne compte que <b>8 mesures</b> : présélection, conditions d'embauche, sensibilisation, processus disciplinaire, responsabilités à la fin du contrat, engagements de confidentialité, <b>travail à distance</b>, signalement des événements."},
{id:"A38", ch:7, d:1, q:"Quelle est la différence de rôle entre l'<b>ISO 27001</b> et l'<b>ISO 27002</b>&nbsp;?", o:["27001 définit le SMSI et ses exigences (elle est certifiable) ; 27002 est le catalogue de bonnes pratiques et la check-list d'audit","27001 est le catalogue, 27002 le système de management","27001 concerne les grandes entreprises, 27002 les PME","27001 est européenne, 27002 internationale"], a:[0], e:"27002 donne à l'organisation «&nbsp;un <b>référentiel de mise en œuvre</b> et une <b>check-list en cas d'audit</b>&nbsp;»."},

/* ---- Ch. 8 : les quatre approches ---- */
{id:"A39", ch:8, d:1, q:"Quelles sont les <b>quatre approches</b> de la cybersécurité&nbsp;?", o:["Centrée sur le système · sur la donnée · sur la menace · sur le métier","Préventive · détective · corrective · réactive","Technique · organisationnelle · humaine · juridique","Stratégique · tactique · opérationnelle · technique"], a:[0], e:"Le support les présente comme les quatre quadrants d'une <b>threat modelling approach</b>. Le calendrier du cours les suit : J1 système puis donnée, J2 menace puis métier."},
{id:"A40", ch:8, d:2, q:"Dans le schéma des quatre angles de vue, quels termes caractérisent l'approche <b>risk based / asset centric</b>&nbsp;?", o:["Likelihood, consequence, impact, supporting assets, asset criticality","Storage, transmitting, classification, processing","Vulnerability, network, design, operating system","TTP, intent, motivation, capabilities"], a:[0], e:"Ce sont les termes du <b>métier</b> : la vraisemblance, la conséquence, l'impact, les <b>biens supports</b> et la <b>criticité de l'actif</b>. On les retrouvera en EBIOS RM."},
{id:"A41", ch:8, d:2, q:"L'approche centrée sur la <b>menace</b> part de quoi&nbsp;?", o:["De l'attaquant : ses TTP, son intention, sa motivation, ses ressources, ses capacités, ses outils, son comportement","Des vulnérabilités du système","De la valeur des données","Des obligations réglementaires"], a:[0], e:"C'est le terrain de la <b>CTI</b>. À l'opposé, l'approche <b>system centric</b> part de l'hôte et du logiciel : vulnérabilité, réseau, conception, système d'exploitation, développement."},
{id:"A42", ch:8, d:3, q:"À quelle approche correspond le <b>modèle zero trust</b>&nbsp;?", o:["L'approche centrée sur la donnée","L'approche centrée sur le système","L'approche centrée sur la menace","L'approche centrée sur le métier"], a:[0], e:"C'est essentiel pour comprendre la précaution finale du support : «&nbsp;une démarche zero trust <b>mal maîtrisée</b> pourra mettre une <b>emphase excessive sur la donnée</b>&nbsp;» — c'est-à-dire confondre un quadrant avec le tableau entier."},

/* ---- Ch. 9 : défense en profondeur ---- */
{id:"A43", ch:9, d:1, q:"Quel est l'objectif de la <b>défense en profondeur</b>, selon sa définition&nbsp;?", o:["Rendre difficile la pénétration des défenses extérieures et, même si elle a lieu, rendre difficile le déplacement latéral et l'accès aux données sensibles","Empêcher toute intrusion","Détecter les intrusions au plus tôt","Chiffrer l'ensemble des données"], a:[0], e:"La seconde moitié de la définition est celle qu'on oublie, et c'est pourtant elle qui rapproche la défense en profondeur du zero trust : on <b>assume</b> que la première barrière peut tomber."},
{id:"A44", ch:9, d:2, q:"Quels sont les <b>trois types de contrôle</b> dans la défense en profondeur&nbsp;?", o:["Physique · technique · administratif","Préventif · détectif · correctif","Réseau · système · applicatif","Humain · organisationnel · technologique"], a:[0], e:"À ne pas confondre avec les <b>types de contrôles</b> des attributs ISO 27002 (#Prévention, #Détection, #Correction)."},
{id:"A45", ch:9, d:3, q:"Quelles sont les <b>deux hypothèses</b> de la défense en profondeur que le support remet en cause&nbsp;?", o:["Que l'attaquant est à l'extérieur, et que le défenseur est passif","Que le périmètre est étanche, et que les mesures sont indépendantes","Que les utilisateurs sont formés, et que les correctifs sont appliqués","Que le budget est illimité, et que l'équipe est compétente"], a:[0], e:"La première mène au <b>zero trust</b> — «&nbsp;que se passe-t-il lorsque l'attaquant est <b>déjà à l'intérieur</b>&nbsp;?&nbsp;». La seconde mène à la <b>défense active</b> : détecter, suivre, ralentir, tromper, contenir, réagir."},
{id:"A46", ch:9, d:2, q:"Quels éléments <b>légitimes</b> le support cite-t-il comme points de départ des attaques modernes&nbsp;?", o:["Un compte utilisateur compromis","Un administrateur victime de phishing","Un partenaire ou sous-traitant compromis","Une application cloud vulnérable","Un balayage de ports depuis Internet"], a:[0,1,2,3], e:"Avec le <b>poste de travail infecté</b> et l'<b>erreur humaine ou mauvaise configuration</b>. Conséquence : «&nbsp;le réseau interne <b>ne peut plus être considéré comme une zone de confiance</b>&nbsp;»."},
{id:"A47", ch:9, d:2, q:"Quelles sont les <b>sept couches</b> de la défense en profondeur illustrées par l'IEC 62443&nbsp;?", o:["Organisationnel et humain · accès physique · périmètre du cyberespace · réseau · machines · applications · données et contrôle d'accès","Physique · liaison · réseau · transport · session · présentation · application","Prévention · détection · réaction · récupération · amélioration · audit · gouvernance","Identité · appareils · applications · données · infrastructure · réseau · visibilité"], a:[0], e:"De l'extérieur vers le cœur. C'est la liste de l'exercice du cours : «&nbsp;citez des mesures de sécurité pour chaque couche&nbsp;»."},
{id:"A48", ch:9, d:1, q:"Que dit le <b>modèle du fromage suisse</b> appliqué à la défense en profondeur&nbsp;?", o:["Chaque couche réduit le risque global : une faille isolée n'expose pas tout le système","Toutes les couches doivent être parfaites","La couche la plus faible détermine le niveau de sécurité","Il faut au minimum sept couches"], a:[0], e:"Ce qui protège, c'est que les trous <b>ne s'alignent pas</b> — ce qui justifie aussi la <b>diversité</b> des mesures : des couches trop semblables ont des trous au même endroit."},
{id:"A49", ch:9, d:2, q:"Comment le support situe-t-il la norme <b>IEC 62443</b>&nbsp;?", o:["L'IEC 62443 est à l'industrie ce que l'ISO/IEC 27001 est à la bureautique — une référence pour l'OT, le SCADA, l'ICS","C'est la version européenne de l'ISO 27001","C'est une méthode d'analyse de risque industrielle","C'est un cadre de certification de produits"], a:[0], e:"Dans le tableau obligations / normes / méthodes, la <b>CEI 62443</b> figure bien dans la colonne <b>normes</b>, comme norme de <b>sécurité industrielle</b>."},

/* ---- Ch. 10 : CTI ---- */
{id:"A50", ch:10, d:1, q:"Selon l'ANSSI, la <b>CTI</b> implique l'ensemble des activités de…", o:["recueil, d'étude et de partage d'informations liées à des attaques informatiques","détection, de blocage et de remédiation des attaques","surveillance, d'alerte et de réponse aux incidents","collecte, de corrélation et d'archivage des journaux"], a:[0], e:"Son but : «&nbsp;fournir des <b>connaissances qualifiées et adaptées</b> à de multiples destinataires souhaitant protéger des systèmes numériques&nbsp;». Le mot <b>partage</b> est important : la CTI est une activité collective."},
{id:"A51", ch:10, d:2, q:"Selon le schéma du cours, une <b>menace</b> est l'intersection de quoi&nbsp;?", o:["Capacités × intentions hostiles × opportunités","Menace × vulnérabilité × impact","Probabilité × gravité","Actif × vulnérabilité × attaquant"], a:[0], e:"Une menace n'existe que si les <b>trois</b> cercles se recoupent : un attaquant <b>capable</b>, <b>qui veut</b>, et <b>qui peut</b>. Supprimer <b>un seul</b> des trois suffit — et c'est sur l'<b>opportunité</b> que le défenseur a le plus de prise."},
{id:"A52", ch:10, d:2, q:"Quelles sont les <b>cinq étapes</b> du cycle du renseignement&nbsp;?", o:["Expression des besoins → collecte → traitement → analyse → diffusion","Collecte → analyse → décision → action → retour","Identifier → protéger → détecter → répondre → récupérer","Plan → do → check → act → improve"], a:[0], e:"En anglais : <i>direction → collection → processing → analysis → dissemination</i>. C'est un <b>cycle</b> : la diffusion nourrit l'expression des besoins suivante."},
{id:"A53", ch:10, d:3, q:"Que sont les <b>PIR</b> dans le cycle du renseignement&nbsp;?", o:["Les Priority Intelligence Requirements — les besoins prioritaires formulés à l'étape direction","Les Points d'Intérêt Réseau","Les Protocoles d'Investigation Rapide","Les Périmètres d'Investigation Restreints"], a:[0], e:"L'étape <b>direction</b> comporte deux choses : <b>fixer les objectifs</b> (<i>setting objectives</i>) et <b>formuler les PIR</b>. Sans elles, la collecte part dans tous les sens."},
{id:"A54", ch:10, d:2, q:"Dans quelle étape du cycle CTI range-t-on l'<b>enrichissement en contexte</b> (aggregation &amp; enrichment)&nbsp;?", o:["Le traitement (processing)","La collecte","L'analyse","La diffusion"], a:[0], e:"Le traitement «&nbsp;traite les données de façon qualitative et quantitative&nbsp;» puis les <b>enrichit en contexte</b>. C'est l'<b>analyse</b> qui produit ensuite le <i>threat actor tracking</i>, la <b>modélisation de la menace</b> et l'<b>attribution</b>."},
{id:"A55", ch:10, d:3, q:"Quels formats d'<b>intégration technique</b> relèvent de l'étape de diffusion&nbsp;?", o:["YARA, SIGMA, SNORT, STIX, IoC (hachés, domaines)","PDF, PowerPoint, tableur","SIEM, SOAR, EDR","MITRE ATT&amp;CK, CVE, CVSS"], a:[0], e:"La diffusion se fait sous deux formes : le <b>rapport qualitatif</b> (stratégique, tactique, opérationnel) pour les humains, et l'<b>intégration technique</b> pour les outils. Destinataires : <b>internes</b> (SOC, CSIRT, direction) et <b>externes</b> (CERT, communauté, partenaires du secteur)."},

/* ---- Ch. 11 : analyse de risque ---- */
{id:"A56", ch:11, d:1, q:"Qu'est-ce qui caractérise l'<b>approche centrée sur le métier</b>&nbsp;?", o:["On ne part pas de la technologie, mais des actifs critiques pour l'organisation","On part des vulnérabilités techniques connues","On part du budget disponible","On part des obligations réglementaires"], a:[0], e:"La cybersécurité y est vue comme un <b>levier de protection de la valeur métier</b>. La priorisation des mesures se fait «&nbsp;selon la <b>valeur business protégée</b>&nbsp;»."},
{id:"A57", ch:11, d:2, q:"Que vise l'analyse de risque, selon la définition du cours&nbsp;?", o:["Identifier les menaces et vulnérabilités, estimer la probabilité, mesurer les conséquences, et fournir une base rationnelle pour décider du traitement","Éliminer tous les risques identifiés","Calculer le coût d'un incident","Vérifier la conformité réglementaire"], a:[0], e:"C'est un «&nbsp;processus structuré d'<b>identification, d'évaluation et de hiérarchisation</b> des risques&nbsp;». Le mot <b>hiérarchisation</b> est essentiel : on ne traite pas tout."},
{id:"A58", ch:11, d:2, q:"Sur quelles démarches globales l'approche métier s'aligne-t-elle&nbsp;?", o:["ISO 27005 et EBIOS RM","ISO 27001 et ITIL","NIS 2 et le Cybersecurity Act","IEC 62443 et ISO 21434"], a:[0], e:"<b>ISO 27005</b> est la <b>norme</b> (lignes directrices de gestion des risques) ; <b>EBIOS RM</b> est la <b>méthode</b> française de référence. La distinction norme/méthode du chapitre 1 se rejoue ici."},

/* ---- Ch. 12 : zero trust, constat ---- */
{id:"A59", ch:12, d:1, q:"Quelles évolutions expliquent l'<b>augmentation de la surface d'attaque</b> dans le constat zero trust&nbsp;?", o:["Le cloud, l'IoT, l'industrie 4.0 et le DevOps","La généralisation du chiffrement","La croissance du nombre de normes","La centralisation des centres de données"], a:[0], e:"Des environnements «&nbsp;<b>hybrides, complexes ou éphémères</b>&nbsp;». Les deux autres éléments du constat : le <b>développement du cybercrime</b> notamment contre les <b>OIV</b>, et l'avènement du <b>nomadisme</b> et du <b>BYOD</b>."},
{id:"A60", ch:12, d:2, q:"Quel principe le zero trust remet-il fondamentalement en cause&nbsp;?", o:["Le principe de confiance implicite accordée à l'accédant et à l'emplacement depuis lequel l'accès est demandé","Le principe de moindre privilège","Le principe de défense en profondeur uniquement","Le principe de séparation des tâches"], a:[0], e:"Il s'agit de «&nbsp;<b>dépasser</b> le principe de défense en profondeur et de passer d'un <b>modèle périmétrique</b> à un <b>modèle axé sur l'identité et le contrôle d'accès</b>&nbsp;»."},
{id:"A61", ch:12, d:2, q:"À quoi le support compare-t-il la présomption du modèle zero trust&nbsp;?", o:["Au procès médiéval, où l'accusé est présumé coupable jusqu'à preuve du contraire","Au procès moderne, où l'accusé est présumé innocent","À l'état de siège","À la quarantaine sanitaire"], a:[0], e:"«&nbsp;Dans le modèle zero trust, <b>chaque tentative de connexion est considérée comme illégitime</b> jusqu'à preuve du contraire.&nbsp;» C'est une <b>présomption de culpabilité</b>."},
{id:"A62", ch:12, d:1, q:"Quel document de référence définit le modèle zero trust&nbsp;?", o:["Le NIST Special Publication 800-207, Zero Trust Architecture, 2020","L'ISO 27001:2022","La directive NIS 2","Le guide ANSSI de la maîtrise du risque numérique"], a:[0], e:"Définition : «&nbsp;un ensemble de <b>paradigmes de cybersécurité en évolution</b>, qui font passer les défenses d'un <b>périmètre statique basé sur le réseau</b> à un périmètre <b>centré sur les utilisateurs, les actifs et les ressources</b>&nbsp;»."},
{id:"A63", ch:12, d:3, q:"Quel est l'<b>objectif</b> du modèle zero trust selon le NIST&nbsp;?", o:["Empêcher l'accès non autorisé aux données et aux services, tout en rendant le contrôle d'accès aussi granulaire que possible","Supprimer tout accès distant","Chiffrer l'intégralité du trafic interne","Remplacer les pare-feu par des proxys"], a:[0], e:"Deux mots comptent dans la définition : «&nbsp;<b>paradigmes</b>&nbsp;» au pluriel — ce n'est pas une technologie — et «&nbsp;<b>en évolution</b>&nbsp;» — ce n'est pas un état à atteindre une fois pour toutes."},

/* ---- Ch. 13 : les trois principes ---- */
{id:"A64", ch:13, d:1, q:"Quels sont les <b>trois principes</b> du modèle zero trust&nbsp;?", o:["Vérifier explicitement · implémenter l'accès à moindre privilège · surveillance continue","Authentifier · autoriser · auditer","Chiffrer · segmenter · journaliser","Identifier · protéger · détecter"], a:[0], e:"Ce sont les trois à réciter dans l'ordre. Ils se retrouvent tels quels dans les consignes du TP."},
{id:"A65", ch:13, d:2, q:"Que recouvre exactement le principe «&nbsp;<b>vérifier explicitement</b>&nbsp;»&nbsp;?", o:["Contrôler dynamiquement le contexte de l'accédant — identité, lieu d'accès, appareil, état de santé — en présumant ouvertement la compromission","Exiger un mot de passe complexe à chaque connexion","Valider manuellement chaque demande d'accès","Vérifier la signature de tous les binaires"], a:[0], e:"Le terme anglais pour cette présomption est «&nbsp;<b>assume breach</b>&nbsp;». Ce n'est pas un contrôle plus strict : c'est un contrôle <b>contextuel et dynamique</b>."},
{id:"A66", ch:13, d:2, q:"Comment le zero trust affine-t-il le principe du <b>moindre privilège</b>&nbsp;?", o:["En attribuant une fenêtre temporelle pour l'accès","En limitant le nombre de comptes administrateurs","En exigeant une double validation","En supprimant les droits par défaut tous les mois"], a:[0], e:"Le privilège est accordé «&nbsp;<b>en fonction de ce contexte</b>&nbsp;», uniquement pour ce qui est nécessaire, et peut être <b>borné dans le temps</b> — d'où les briques <b>PAM</b> et les accès <b>juste-à-temps</b>."},
{id:"A67", ch:13, d:3, q:"Quels trois adjectifs distinguent le contrôle zero trust d'un contrôle d'accès classique&nbsp;?", o:["Dynamique · continu · granulaire","Strict · centralisé · automatisé","Chiffré · authentifié · journalisé","Préventif · détectif · correctif"], a:[0], e:"<b>Dynamique</b> : le contexte est réévalué. <b>Continu</b> : la vérification ne s'arrête pas à l'authentification initiale. <b>Granulaire</b> : le contrôle porte sur la ressource, pas sur le réseau."},

/* ---- Ch. 14 : piliers et architecture ---- */
{id:"A68", ch:14, d:1, q:"Quels sont les <b>six piliers technologiques</b> du zero trust&nbsp;?", o:["Identité · appareils · applications · données · infrastructure · réseau","Identité · réseau · cloud · données · applications · gouvernance","Utilisateurs · terminaux · serveurs · réseau · données · journaux","Prévention · détection · réponse · récupération · gouvernance · conformité"], a:[0], e:"Ils sont chapeautés par <b>visibilité, automatisation, orchestration</b> — la couche transverse sans laquelle les six piliers ne communiquent pas."},
{id:"A69", ch:14, d:2, q:"Quel pilier le support désigne-t-il comme <b>prioritaire</b>&nbsp;?", o:["L'identité — les autres étant traités selon leur importance et leur maturité dans l'organisation","Le réseau","Les données","L'infrastructure"], a:[0], e:"Dans l'infographie <i>Securing identities with Zero Trust</i>, <b>appareils (38&nbsp;%)</b> et <b>identités (24&nbsp;%)</b> pèsent ensemble <b>62&nbsp;%</b>, contre seulement <b>1&nbsp;%</b> pour les applications."},
{id:"A70", ch:14, d:2, q:"Pourquoi le support déconseille-t-il une <b>bascule complète</b> vers le zero trust&nbsp;?", o:["Parce qu'elle est peu envisageable pour les entités dotées d'un patrimoine informatique hérité et sédimenté","Parce que les licences sont trop coûteuses","Parce que la réglementation l'interdit","Parce qu'il faut d'abord être certifié ISO 27001"], a:[0], e:"D'où le conseil de <b>mise en œuvre progressive</b>, et le point de vigilance sur la <b>dépendance entre les piliers, aussi bien fonctionnelle que commerciale</b> — le risque d'enfermement chez un éditeur."},
{id:"A71", ch:14, d:3, q:"Dans l'architecture zero trust, que contient le bloc <b>Policy Optimization</b>&nbsp;?", o:["Gouvernance, conformité, évaluation de la posture de sécurité, optimisation de la productivité","Chiffrement, segmentation, filtrage, journalisation","Authentification, autorisation, audit","Collecte, analyse, diffusion"], a:[0], e:"À distinguer du bloc <b>Threat Protection</b> : évaluation continue, <b>threat intelligence</b>, <b>forensics</b>, <b>automatisation de la réponse</b>. Les deux alimentent la <b>Zero Trust Policy</b> centrale."},
{id:"A72", ch:14, d:2, q:"Dans l'architecture de référence, quels types d'<b>identités</b> et de <b>terminaux</b> sont prévus&nbsp;?", o:["Identités humaines et non humaines ; terminaux d'entreprise et personnels","Identités humaines uniquement ; terminaux d'entreprise uniquement","Identités internes uniquement ; terminaux gérés uniquement","Identités fédérées uniquement ; terminaux mobiles uniquement"], a:[0], e:"Le <b>BYOD</b> est donc explicitement dans le modèle, de même que les <b>comptes de service</b> et les identités machine — c'est une conséquence directe du constat de départ."},

/* ---- Ch. 15 : le PEP ---- */
{id:"A73", ch:15, d:1, q:"Que contrôle le moteur d'évaluation au cœur de l'architecture zero trust&nbsp;?", o:["Deux propriétés fondamentales : l'authentification et l'autorisation","Le chiffrement et l'intégrité","La disponibilité et la performance","La conformité et la traçabilité"], a:[0], e:"Et il le fait <b>en temps réel</b>, à chaque demande d'accès."},
{id:"A74", ch:15, d:2, q:"Répartissez les rôles&nbsp;: qui <b>décide</b>, qui <b>applique</b>, qui <b>administre</b>&nbsp;?", o:["Le PE décide · le PEP applique · le PA configure et gère les PEP","Le PEP décide · le PE applique · le PA supervise","Le PA décide · le PE applique · le PEP journalise","Le PDP applique · le PEP décide · le PA audite"], a:[0], e:"<b>PE</b> = Policy Engine · <b>PEP</b> = Policy Enforcement Point · <b>PA</b> = Policy Administrator · <b>PDP</b> = Policy Decision Point, qui regroupe PE et PA."},
{id:"A75", ch:15, d:2, q:"Quelles sont les <b>quatre entrées</b> du PEP&nbsp;?", o:["L'identité · le terminal · la politique · la protection","Les données · les applications · l'infrastructure · le réseau","L'utilisateur · le lieu · l'heure · l'appareil","L'authentification · l'autorisation · l'audit · la journalisation"], a:[0], e:"Ce sont les <b>éléments de contexte</b> qui servent à décider : <b>qui</b>, <b>avec quoi</b>, <b>selon quelles règles</b>, <b>dans quel état de menace</b>."},
{id:"A76", ch:15, d:2, q:"Quelles sont les <b>quatre sorties</b> du PEP&nbsp;?", o:["Données · applications · infrastructure · réseau","Identité · terminal · politique · protection","Prévention · détection · réponse · récupération","Confidentialité · intégrité · disponibilité · traçabilité"], a:[0], e:"Les sorties correspondent à <b>quatre des six piliers</b>. Les deux qui manquent — <b>identité</b> et <b>appareils</b> — sont justement les <b>entrées</b>. C'est la symétrie à repérer."},
{id:"A77", ch:15, d:3, q:"Selon la définition du support, que recouvre le terme <b>« terminal »</b> en zero trust&nbsp;?", o:["Tout bien — matériel, logiciel, micrologiciel — pouvant se connecter à un réseau : serveurs, postes, imprimantes, téléphones, IoT, équipements réseau","Les postes de travail et les portables uniquement","Les appareils gérés par la DSI uniquement","Les terminaux mobiles sous MDM"], a:[0], e:"La définition est volontairement très large, et c'est ce qui explique que le pilier <b>appareils</b> pèse <b>38&nbsp;%</b> : l'imprimante et l'objet connecté en font partie."},
{id:"A78", ch:15, d:3, q:"Quelle <b>quatrième question</b> le moteur d'évaluation peut-il poser, au-delà de l'identité, de l'autorisation et de l'appareil&nbsp;?", o:["S'il y a d'autres facteurs à prendre en compte — l'heure, la localisation du sujet","Si le budget de l'accès est disponible","Si le responsable hiérarchique a validé","Si la ressource est sauvegardée"], a:[0], e:"C'est ce qui rend le contrôle <b>contextuel</b>. On retrouve ces facteurs dans la sortie <b>Applications</b> : «&nbsp;restriction des accès en fonction du contexte des demandes, <b>dans l'espace et dans le temps</b>&nbsp;»."},

/* ---- Ch. 16 : briques et quick wins ---- */
{id:"A79", ch:16, d:1, q:"Qu'est-ce qu'un <b>quick win</b>&nbsp;?", o:["Une action simple, demandant peu d'implication, en échange de résultats rapides et tangibles","Une mesure gratuite","Une mesure appliquée en moins d'une semaine","Une mesure qui ne nécessite aucun outil"], a:[0], e:"Il est défini <b>par rapport à un périmètre</b> — typiquement les actifs les plus critiques — peut être <b>visible ou non</b>, mais doit <b>toujours être mesurable</b>."},
{id:"A80", ch:16, d:1, q:"Quel est l'<b>exemple typique</b> de quick win donné par le support, et quel gain chiffré lui associe-t-il&nbsp;?", o:["Le MFA — ou mieux l'authentification sans mot de passe — qui réduit de plus de 99 % les attaques sur l'identité","Le chiffrement de disque, qui supprime 80 % des fuites","La segmentation réseau, qui divise par deux la surface d'attaque","L'EDR, qui détecte 95 % des maliciels"], a:[0], e:"Chiffre issu de <i>Evolving Zero Trust</i>, Microsoft, nov. 2021. Autres exemples de quick wins : le <b>SSO</b> (identité), l'<b>EDR</b> (terminaux), et la <b>suppression des actifs obsolètes inutilisés</b>."},
{id:"A81", ch:16, d:2, q:"Quelles briques technologiques relèvent du pilier <b>identité</b>&nbsp;?", o:["SSO","IAM","PAM","MFA","EDR"], a:[0,1,2,3], e:"Pour les <b>terminaux</b> : <b>EDR</b>, <b>NAC</b>, <b>MDM</b>. Pour le <b>réseau</b> : segmentation, micro-segmentation, chiffrement du trafic."},
{id:"A82", ch:16, d:2, q:"Qu'est-ce qu'un <b>CASB</b>&nbsp;?", o:["Un logiciel situé entre les utilisateurs de services cloud et les applications cloud, qui surveille l'activité, alerte, applique les politiques et bloque les maliciels","Un pare-feu applicatif pour le cloud","Un courtier en certificats pour les API","Un système de sauvegarde cloud chiffré"], a:[0], e:"<i>Cloud Access Security Broker</i>. Il est rangé dans les briques du pilier <b>infrastructure</b>, avec la gestion des versions <b>JIT</b> des IaaS, PaaS, VM et conteneurs."},
{id:"A83", ch:16, d:3, q:"Pourquoi la <b>protection contre les rançongiciels</b> est-elle citée comme un cas complexe&nbsp;?", o:["Parce qu'elle implique plusieurs piliers à la fois, et non un nombre restreint de briques","Parce qu'aucune brique technologique ne la couvre","Parce qu'elle relève du cadre réglementaire","Parce qu'elle exige un budget particulier"], a:[0], e:"«&nbsp;Certaines attentes simples mobiliseront un <b>nombre restreint</b> de briques, d'autres impliquant <b>plusieurs piliers</b> sont plus complexes à décliner.&nbsp;»"},

/* ---- Ch. 17 : conduire le projet ---- */
{id:"A84", ch:17, d:2, q:"Quels sont les arguments à avancer pour un projet zero trust&nbsp;?", o:["Sécurité et adaptabilité","Opportunités et contrôle des données","Conformité","Intégration du cloud","Réduction immédiate du nombre d'incidents"], a:[0,1,2,3], e:"Six arguments au total. L'<b>adaptabilité</b> couvre le télétravail, les <b>identités externes</b> et la <b>facilitation des fusions-acquisitions</b> ; l'<b>intégration du cloud</b> passe par une gestion stricte des identités qui <b>limite le Shadow IT</b>."},
{id:"A85", ch:17, d:1, q:"Qu'est-ce que le <b>Shadow IT</b>&nbsp;?", o:["Les SI réalisés et mis en œuvre au sein d'une organisation sans approbation de la DSI","Les systèmes hébergés sur le darkweb","Les systèmes non inventoriés par le SOC","Les environnements de test non supervisés"], a:[0], e:"Exemples donnés : le <b>BYOD</b>, les <b>solutions <i>drive</i></b>, les <b>classeurs Excel comprenant des macros</b>. Aussi appelé <i>Rogue IT</i>."},
{id:"A86", ch:17, d:2, q:"Sur quel principe repose l'argument «&nbsp;sécurité&nbsp;» du zero trust&nbsp;?", o:["Le principe Assume Breach, qui prend en compte les menaces ciblant tous les secteurs","Le principe de défense en profondeur","Le principe du chiffrement de bout en bout","Le principe de séparation des privilèges"], a:[0], e:"Tous les secteurs sont cités : <b>privés, gouvernementaux, ONG, académies</b>."},
{id:"A87", ch:17, d:3, q:"Parmi les besoins exprimés dans «&nbsp;je veux pouvoir…&nbsp;», lequel touche directement l'annuaire d'entreprise&nbsp;?", o:["Minimiser la surface d'attaque de mon annuaire AD","Rationaliser mes solutions de sécurité","Garantir ma conformité au RGPD","Offrir plus de flexibilité à mes utilisateurs"], a:[0], e:"La liste mélange volontairement des besoins de <b>sécurité</b>, de <b>conformité</b>, de <b>coût</b> et de <b>confort</b> — c'est ce qui permet de porter le projet devant une direction."},

/* ---- Ch. 18 : compléments ---- */
{id:"A88", ch:18, d:2, q:"Qu'est-ce qui distingue la <b>micro-segmentation</b> de la segmentation classique&nbsp;?", o:["Politiques granulaires, réseau virtuel, trafic est-ouest, couche 4, SDN et conteneurisation, logiciel","Politiques générales, réseau physique, trafic nord-sud, couches 2 et 3, VLAN, matériel","Elle ne s'applique qu'au cloud public","Elle remplace le chiffrement des flux"], a:[0], e:"La segmentation classique, elle, est <b>matérielle</b> : réseau physique, trafic <b>nord-sud</b>, couches <b>2 et 3</b>, <b>VLAN, MPLS, pare-feu</b>, découpage <b>géographique et fonctionnel</b>."},
{id:"A89", ch:18, d:1, q:"Que désigne le trafic <b>est-ouest</b>&nbsp;?", o:["Le trafic entre les appareils au sein d'un centre de données","Le trafic entrant et sortant d'un centre de données","Le trafic entre deux centres de données distants","Le trafic chiffré entre continents"], a:[0], e:"Le trafic <b>nord-sud</b> est celui qui <b>entre et sort</b> d'un centre de données. La micro-segmentation vise l'est-ouest, c'est-à-dire précisément le <b>déplacement latéral</b> de l'attaquant."},
{id:"A90", ch:18, d:2, q:"Quelle est la différence entre <b>ZTA</b> et <b>ZTNA</b>&nbsp;?", o:["ZTA est l'approche appliquée à l'accès aux ressources ; ZTNA est la technologie qui sécurise l'accès réseau","ZTA est la technologie, ZTNA l'approche","ZTA concerne le cloud, ZTNA le sur site","Ce sont deux noms du même concept"], a:[0], e:"La phrase de synthèse : «&nbsp;<b>Zero Trust est le principe global, ZTA est son application à l'accès aux ressources, et ZTNA met en œuvre ces principes pour sécuriser l'accès réseau.</b>&nbsp;» Attention : le support signale qu'il ne faut pas confondre ce ZTA avec <i>Zero Trust Architecture</i>, parfois aussi abrégé ZTA."},
{id:"A91", ch:18, d:3, q:"En quoi le <b>ZTNA</b> se distingue-t-il d'un <b>VPN</b>&nbsp;?", o:["Il agit au-delà du réseau et réduit la surface d'attaque en cachant les applications de l'Internet","Il chiffre plus fortement le tunnel","Il ne nécessite pas d'authentification","Il fonctionne uniquement en interne"], a:[0], e:"Fonctionnement : il <b>bloque par défaut tous les accès</b>, n'autorise que les utilisateurs approuvés, et crée des <b>tunnels chiffrés pour chaque session d'application</b>. Le VPN, lui, place le poste <b>sur le réseau</b> — exactement le modèle périmétrique qu'on cherche à quitter."},
{id:"A92", ch:18, d:2, q:"Comment le support oppose-t-il <b>zero trust</b> (Forrester) et <b>SASE</b> (Gartner)&nbsp;?", o:["Le zero trust met l'accent sur l'identité et le terminal ; SASE met en avant le réseau et l'infrastructure","Le zero trust est cloud, SASE est sur site","Le zero trust est américain, SASE européen","Le zero trust concerne les données, SASE les applications"], a:[0], e:"SASE est «&nbsp;une vision <b>complètement cloud</b>&nbsp;», centrée sur le <b>SD-WAN</b> préféré au <b>MPLS</b> — ce qui lui vaut d'être qualifiée de «&nbsp;<b>périmétrique dans le cloud</b>&nbsp;». Le zero trust est plus <b>agnostique</b> : il prend en compte les SI sur site."},
{id:"A93", ch:18, d:2, q:"Qu'est-ce que le <b>triangle LWC</b> de la cryptographie légère&nbsp;?", o:["Le compromis entre performance, sécurité et coût","Le compromis entre confidentialité, intégrité et disponibilité","Les trois tailles de clé normalisées","Les trois modes de chiffrement par bloc"], a:[0], e:"Elle est conçue pour les <b>dispositifs à contraintes de ressources</b> : la <b>taille de clé</b> peut être ajustée (par exemple <b>64 bits</b>) et le <b>nombre de tours</b> réduit (par exemple <b>16 cartouches</b>). Idéale pour l'<b>IoT</b> et les <b>réseaux de capteurs sans fil</b>."},
{id:"A94", ch:18, d:2, q:"Pourquoi le zero trust met-il en avant le <b>chiffrement homomorphe</b>&nbsp;?", o:["Parce qu'il permet de traiter des données chiffrées sans les déchiffrer","Parce qu'il est plus rapide que le chiffrement classique","Parce qu'il ne nécessite pas de gestion de clés","Parce qu'il est imposé par le RGPD"], a:[0], e:"Quatre raisons dans le support : <b>sécurité des données</b>, <b>confidentialité</b> (même en cas de partage avec des tiers), <b>conformité</b>, et <b>réduction des risques</b> en minimisant les points d'exposition."},
{id:"A95", ch:18, d:3, q:"Quel <b>risque</b> l'IA générative introduit-elle, selon le support&nbsp;?", o:["Des risques de fuite de données relevant du shadow IT — que la DLP permet de suivre","Des risques d'injection de prompt dans les pare-feu","Des risques de saturation des journaux","Des risques de non-conformité à l'ISO 27001"], a:[0], e:"L'IA a aussi deux effets positifs sur le zero trust : elle <b>fournit des informations</b> sur les données et les événements liés aux identités, et elle <b>améliore le renseignement sur les menaces en temps réel</b> et l'<b>automatisation des réponses</b>."},

/* ---- Ch. 19 : précautions ---- */
{id:"A96", ch:19, d:2, q:"Quel travers guette une démarche zero trust <b>mal maîtrisée</b>&nbsp;?", o:["Mettre une emphase excessive sur la donnée, au détriment des trois autres approches","Négliger le chiffrement des flux","Multiplier les pare-feu périmétriques","Sur-investir dans la formation"], a:[0], e:"Le zero trust <b>est</b> l'approche centrée sur la donnée. Le prendre pour toute la sécurité revient à confondre un quadrant avec le tableau entier : «&nbsp;la cybersécurité est une affaire d'<b>équilibre</b> entre quatre grandes approches&nbsp;»."},
{id:"A97", ch:19, d:3, q:"Que met en garde l'<b>ANSSI</b> à propos du zero trust&nbsp;?", o:["Que faute de maturité, le déploiement peut accroître la vulnérabilité des SI et donner un faux sentiment de sécurité","Qu'il est incompatible avec le RGPD","Qu'il ne s'applique pas aux OIV","Qu'il doit être précédé d'une certification ISO 27001"], a:[0], e:"«&nbsp;Le recours à ces solutions est <b>ardu</b>, faute de maturité : le déploiement est susceptible d'entraîner des <b>erreurs d'installation ou de configuration</b>…&nbsp;»"},
{id:"A98", ch:19, d:2, q:"Sur quoi le zero trust ne dispense-t-il pas d'une réflexion autonome&nbsp;?", o:["Le chiffrement des flux","Les jetons d'authentification","La journalisation","La sensibilisation des utilisateurs","Le choix de l'éditeur de la solution"], a:[0,1,2,3], e:"Les quatre sont cités dans la conclusion. Et la phrase finale : «&nbsp;<b>tout dépend des objectifs visés et surtout du niveau de maturité déjà atteint par le SI</b>&nbsp;»."},

/* ---- Ch. 20 : TP et devoir ---- */
{id:"A104", ch:13, d:3, q:"Un collaborateur se connecte à distance depuis un poste dont l'état de santé est inconnu. Quel principe zero trust est en cause en premier&nbsp;?", o:["La vérification explicite — elle porte sur l'identité et sur le terminal","Le moindre privilège — le compte a trop de droits","La micro-segmentation — les flux internes ne sont pas filtrés","La surveillance continue — l'activité n'est pas journalisée"], a:[0], e:"La vérification explicite ne se limite pas à «&nbsp;qui êtes-vous&nbsp;»&nbsp;: l'<b>état de santé de l'appareil</b> fait partie du contexte évalué à chaque demande d'accès. Un VPN classique reproduit exactement le <b>modèle périmétrique</b> qu'on cherche à quitter — il authentifie une fois, puis place le poste «&nbsp;à l'intérieur&nbsp;». La réponse structurelle est le <b>ZTNA</b>, épaulé par le <b>NAC</b>, le <b>MDM</b> et l'<b>EDR</b> pour évaluer la conformité du terminal."},

/* ---- Ch. 21 : EBIOS RM, la démarche ---- */
{id:"B01", ch:21, d:1, q:"Qui publie la méthode <b>EBIOS Risk Manager</b>, et avec quel soutien&nbsp;?", o:["L'ANSSI, avec le soutien du Club EBIOS","L'ISO, avec le soutien de la CNIL","L'ENISA, avec le soutien de l'ANSSI","Le NIST, avec le soutien du Club EBIOS"], a:[0], e:"Le <b>Club EBIOS</b> est une association loi 1901 qui enrichit le référentiel français depuis <b>2003</b>. <i>EBIOS</i> est une <b>marque déposée</b> par le Secrétariat général de la défense et de la sécurité nationale."},
{id:"B02", ch:21, d:2, q:"Avec quelles normes EBIOS RM est-elle alignée&nbsp;?", o:["Conforme à ISO/IEC 27005:2022, compatible avec ISO 31000:2018","Conforme à ISO 27001, compatible avec ISO 9000","Conforme à NIS 2, compatible avec le RGPD","Conforme à l'IEC 62443"], a:[0], e:"C'est la raison d'être de la mise à jour du guide : «&nbsp;rendre la méthode <b>pleinement conforme à la norme ISO/CEI 27005:2022</b>&nbsp;»."},
{id:"B03", ch:21, d:2, q:"Quelles <b>deux approches</b> EBIOS RM combine-t-elle, et pour quels risques&nbsp;?", o:["Une approche par conformité pour le socle et les risques communs, y compris accidentels et environnementaux ; une approche par scénarios pour les risques avancés et intentionnels","Une approche quantitative et une approche qualitative","Une approche technique et une approche organisationnelle","Une approche préventive et une approche réactive"], a:[0], e:"C'est la <b>pyramide du management du risque numérique</b> : à la base, large et simple, les <b>principes de base et l'hygiène</b> ; au milieu le <b>cadre réglementaire et normatif</b> ; au sommet, avancé et ciblé, l'<b>appréciation des risques</b>."},
{id:"B04", ch:21, d:1, q:"Quels sont les <b>noms exacts</b> des cinq ateliers&nbsp;?", o:["Cadrage et socle de sécurité · Sources de risque · Scénarios stratégiques · Scénarios opérationnels · Traitement du risque","Contexte · Menaces · Vulnérabilités · Risques · Mesures","Périmètre · Actifs · Scénarios · Cotation · Plan d'action","Identifier · Protéger · Détecter · Répondre · Récupérer"], a:[0], e:"Les cinq, dans l'ordre. Les <b>ateliers 2, 3 et 4</b> constituent l'<b>appréciation des risques</b> ; l'<b>atelier 1</b> relève de l'approche par <b>conformité</b>."},
{id:"B05", ch:21, d:3, q:"Dans la chaîne logique d'EBIOS RM, <b>où</b> se cote la gravité et <b>où</b> se cote la vraisemblance&nbsp;?", o:["La gravité aux ateliers 1 et 3 ; la vraisemblance à l'atelier 4","La gravité à l'atelier 4 ; la vraisemblance à l'atelier 3","Les deux à l'atelier 5","Les deux à l'atelier 1"], a:[0], e:"C'est l'erreur la plus commune. La <b>gravité</b> est portée par le <b>scénario stratégique</b> et reste <b>identique pour tous ses chemins d'attaque</b> ; la <b>vraisemblance</b> est <b>propre à chaque scénario opérationnel</b>. Le <b>niveau de risque</b> croise les deux."},
{id:"B06", ch:21, d:2, q:"Qu'est-ce qu'un <b>scénario de risque</b>&nbsp;?", o:["L'association d'un chemin d'attaque et de son scénario opérationnel, de la source de risque jusqu'à l'objectif visé","Un scénario stratégique seul","Un scénario opérationnel seul","Un couple SR/OV"], a:[0], e:"«&nbsp;Scénario <b>complet</b>, allant de la source de risque à l'objectif visé, décrivant un chemin d'attaque et le scénario opérationnel associé.&nbsp;» C'est l'unité qu'on cote en <b>gravité × vraisemblance</b>."},
{id:"B07", ch:21, d:2, q:"Quels sont les <b>deux cycles</b> de la démarche, et que revisite chacun&nbsp;?", o:["Un cycle stratégique qui revisite toute l'étude et les scénarios stratégiques ; un cycle opérationnel qui revient sur les scénarios opérationnels","Un cycle annuel et un cycle trimestriel","Un cycle de conception et un cycle d'exploitation","Un cycle interne et un cycle écosystème"], a:[0], e:"Leurs durées sont <b>définies lors du premier atelier</b>. Le cycle opérationnel se déclenche «&nbsp;à la lumière des <b>incidents survenus</b>, de l'apparition de <b>nouvelles vulnérabilités</b> et de l'<b>évolution des modes opératoires</b>&nbsp;»."},
{id:"B08", ch:21, d:3, q:"Comment s'appelle aujourd'hui ce que l'édition 2018 nommait le <b>PACS</b>&nbsp;?", o:["Le plan de traitement du risque","Le plan d'assurance sécurité","Le plan de continuité","La stratégie de traitement du risque"], a:[0], e:"Trois renommages en 2024 pour rapprocher la terminologie de l'ISO : <b>PACS → plan de traitement du risque</b>, <b>entité ou personne responsable → propriétaire</b>, <b>synthèse des scénarios de risque → évaluations des risques</b>. Le sigle PACS reste employé à l'oral."},

/* ---- Ch. 22 : atelier 1 ---- */
{id:"B09", ch:22, d:1, q:"Quelles sont les <b>données de sortie</b> de l'atelier 1&nbsp;?", o:["Les éléments de cadrage ; le périmètre métier et technique (missions, valeurs métier, biens supports) ; les événements redoutés et leur gravité ; le socle de sécurité","Les couples SR/OV et leur cartographie","Les scénarios stratégiques et leur gravité","Le plan de traitement du risque"], a:[0], e:"Le socle comprend la <b>liste des référentiels applicables</b>, l'<b>état d'application</b>, et l'<b>identification et la justification des écarts</b>."},
{id:"B10", ch:22, d:2, q:"Quelle est la différence entre une <b>valeur métier</b> et un <b>bien support</b>&nbsp;?", o:["La valeur métier est ce qu'on protège — service, information, savoir-faire ; le bien support est le composant du SI sur lequel elle repose","La valeur métier est technique, le bien support est métier","La valeur métier appartient à l'écosystème, le bien support à l'organisation","Ce sont deux noms du même objet"], a:[0], e:"On cote des <b>événements redoutés</b> sur les <b>valeurs métier</b> ; on trace des <b>scénarios opérationnels</b> sur les <b>biens supports</b>. Dans EBIOS 2010, la valeur métier s'appelait <b>bien essentiel</b>."},
{id:"B11", ch:22, d:2, q:"Qui participe à l'atelier 1&nbsp;?", o:["Direction, Métiers, RSSI, DSI","RSSI et DSI uniquement","Métiers et Achats","Direction et service juridique"], a:[0], e:"Ce sont <b>les mêmes participants qu'à l'atelier 5</b> : ceux qui cadrent sont ceux qui décident du traitement. L'atelier <b>4</b>, le plus technique, ne réunit que <b>RSSI et DSI</b>."},
{id:"B12", ch:22, d:2, q:"Sur l'échelle de gravité du guide, qu'est-ce qui distingue <b>G3</b> de <b>G4</b>&nbsp;?", o:["En G4, la société ne surmontera vraisemblablement pas la situation — sa survie est menacée ; en G3 elle surmonte avec de sérieuses difficultés","En G4 il y a des impacts sur la sécurité des personnes, pas en G3","En G3 l'activité est arrêtée, en G4 elle est dégradée","G4 concerne l'écosystème, G3 l'organisation"], a:[0], e:"Deux lignes à retenir : entre <b>G2 et G3</b>, l'apparition d'<b>impacts sur la sécurité des personnes et des biens</b> ; entre <b>G3 et G4</b>, la <b>survie de l'organisation</b>. G1 = aucun impact opérationnel, simple consommation des marges."},
{id:"B13", ch:22, d:3, q:"Que dit le guide si l'évaluation du socle révèle des <b>écarts trop significatifs</b>&nbsp;?", o:["Ne pas poursuivre les ateliers d'appréciation des risques","Poursuivre en cotant les risques à la hausse","Passer directement à l'atelier 5","Refaire l'atelier 1 avec un périmètre élargi"], a:[0], e:"Inutile de modéliser une attaque sophistiquée si l'<b>hygiène de base</b> n'est pas en place : il faut d'abord <b>combler le socle</b>. Le guide note d'ailleurs que l'étude du socle «&nbsp;<b>occupe une grande partie</b> du processus d'analyse de risque&nbsp;»."},

/* ---- Ch. 23 : atelier 2 ---- */
{id:"B14", ch:23, d:1, q:"À quelle question l'atelier 2 répond-il&nbsp;?", o:["« Qui ou quoi pourrait porter atteinte aux missions et valeurs métier identifiées dans l'atelier 1, et dans quels buts ? »","« Quelles sont les vulnérabilités de mon SI ? »","« Quelles mesures dois-je mettre en place ? »","« Quel est mon niveau de conformité ? »"], a:[0], e:"D'où le <b>couple SR/OV</b> : la <b>source de risque</b> répond au «&nbsp;qui ou quoi&nbsp;», l'<b>objectif visé</b> au «&nbsp;dans quels buts&nbsp;»."},
{id:"B15", ch:23, d:2, q:"Sur quels <b>trois critères</b> évalue-t-on la pertinence d'un couple SR/OV&nbsp;?", o:["La motivation, les ressources, l'activité de la source de risque","La gravité, la vraisemblance, l'impact","La probabilité, le coût, le délai","L'exposition, la maturité, la confiance"], a:[0], e:"Les <b>ressources</b> regroupent les moyens financiers, les compétences et les infrastructures d'attaque. L'<b>activité</b> demande si la source est active dans le périmètre, l'écosystème, l'industrie concernée ou une industrie similaire."},
{id:"B16", ch:23, d:3, q:"Quel piège de vocabulaire le guide signale-t-il explicitement à l'atelier 2&nbsp;?", o:["Ne pas confondre l'objectif visé et la motivation poussant la source de risque à le réaliser","Ne pas confondre source de risque et menace","Ne pas confondre gravité et impact","Ne pas confondre partie prenante et bien support"], a:[0], e:"L'<b>objectif visé</b> est <b>ce que la source veut obtenir</b> ; la <b>motivation</b> est <b>pourquoi elle le veut</b>. Dans l'exemple du guide, «&nbsp;voler des informations en espionnant la R&amp;D&nbsp;» est l'objectif ; «&nbsp;en vue d'obtenir un avantage concurrentiel&nbsp;» est la motivation."},
{id:"B17", ch:23, d:2, q:"Combien de couples SR/OV le guide recommande-t-il de retenir&nbsp;?", o:["3 à 6, base suffisante pour élaborer des scénarios stratégiques","1 à 2","8 à 12","Autant que possible, sans limite"], a:[0], e:"Et il précise le critère de choix : privilégier des couples <b>suffisamment distincts</b> qui <b>impacteront différentes valeurs métier et biens supports</b>, avec un <b>panel différencié de profils d'attaquant</b> — et <b>sans laisser d'angle mort</b>."},

/* ---- Ch. 24 : atelier 3 ---- */
{id:"B18", ch:24, d:2, q:"Que mesure le <b>niveau de dangerosité</b> d'une partie prenante&nbsp;?", o:["La capacité d'une source de risque à exploiter la relation privilégiée entre cette partie prenante et l'objet de l'étude","L'intention malveillante de la partie prenante","La probabilité qu'elle soit attaquée","Son niveau de conformité réglementaire"], a:[0], e:"Le guide est explicite : le niveau de dangerosité «&nbsp;<b>ne préjuge aucunement d'une intention malveillante</b> de la part de la partie prenante&nbsp;». Un prestataire de ménage n'est pas suspect — il a un accès qu'un attaquant peut détourner."},
{id:"B19", ch:24, d:2, q:"Sur quels critères évalue-t-on les parties prenantes&nbsp;?", o:["Exposition = dépendance × pénétration ; fiabilité cyber = maturité × confiance","Gravité × vraisemblance","Motivation × ressources × activité","Impact × probabilité × détectabilité"], a:[0], e:"La dangerosité <b>croît avec l'exposition</b> et <b>décroît avec la fiabilité cyber</b>. Le guide recommande de privilégier des <b>critères objectifs et opposables</b> plutôt que des facteurs subjectifs."},
{id:"B20", ch:24, d:1, q:"Qu'est-ce qu'un <b>scénario stratégique</b>&nbsp;?", o:["Un chemin d'attaque allant d'une source de risque à un objectif visé, en passant par l'écosystème et les valeurs métier","Un enchaînement d'actions élémentaires sur les biens supports","Un plan de traitement à moyen terme","Une cartographie des parties prenantes"], a:[0], e:"Il est estimé en <b>GRAVITÉ</b> — et cette gravité vaut pour <b>tous</b> ses chemins d'attaque. C'est le scénario <b>opérationnel</b> (atelier 4) qui porte l'enchaînement d'actions sur les biens supports, estimé en <b>vraisemblance</b>."},
{id:"B21", ch:24, d:3, q:"Quels participants sont <b>spécifiques</b> à l'atelier 3&nbsp;?", o:["Les acteurs connaissant les engagements contractuels avec les parties prenantes — Achats ou Service juridique — et les architectes fonctionnels","La direction et les métiers","Le DSI et le RSSI","Les auditeurs internes"], a:[0], e:"C'est logique : l'atelier porte sur l'<b>écosystème</b>, et les leviers d'action y sont largement <b>contractuels</b>. Le guide cite d'ailleurs comme mesures «&nbsp;réduire la dépendance à un sous-traitant&nbsp;» ou «&nbsp;accroître la maturité cyber du…&nbsp;»."},
{id:"B22", ch:24, d:2, q:"Qu'est-ce qu'une <b>partie prenante critique (PPC)</b>&nbsp;?", o:["Une partie prenante susceptible de constituer un vecteur d'attaque privilégié, du fait de son accès numérique privilégié, de sa vulnérabilité ou de son exposition","Une partie prenante indispensable à l'activité","Une partie prenante soumise à NIS 2","Une partie prenante non conforme au socle"], a:[0], e:"Les parties prenantes sont les acteurs «&nbsp;dont le <b>SI est interconnecté</b> avec l'objet de l'étude&nbsp;» ou «&nbsp;pour lesquels des <b>prestations sont réalisées</b>&nbsp;» — l'infogérance par exemple."},

/* ---- Ch. 25 : atelier 4 ---- */
{id:"B23", ch:25, d:1, q:"Quelle <b>séquence d'attaque</b> le guide utilise-t-il dans son exemple de scénario opérationnel&nbsp;?", o:["Connaître → Rentrer → Trouver → Exploiter","Reconnaissance → Armement → Livraison → Installation","Identifier → Protéger → Détecter → Répondre","Préparer → Pénétrer → Persister → Exfiltrer"], a:[0], e:"Le guide précise que <b>plusieurs modèles existent</b> et cite la <b>cyber kill chain de Lockheed Martin</b>. Le graphe peut porter des opérateurs <b>ET</b> (les deux actions sont nécessaires) et <b>OU</b> (l'une ou l'autre suffit)."},
{id:"B24", ch:25, d:2, q:"Que confronte l'évaluation de la <b>vraisemblance</b> d'un scénario opérationnel&nbsp;?", o:["Les ressources et la motivation présumées de la source de risque, face au socle de sécurité et au niveau de vulnérabilité de l'écosystème","La gravité et l'impact","Le coût de l'attaque et le gain espéré","Le nombre de vulnérabilités connues"], a:[0], e:"Le niveau de vulnérabilité comprend la <b>surface d'attaque exposée</b>, les vulnérabilités <b>structurelles et organisationnelles</b>, et les <b>capacités de détection et de réaction</b>."},
{id:"B25", ch:25, d:2, q:"Sur l'échelle de vraisemblance, que signifie <b>V3</b>&nbsp;?", o:["Très vraisemblable : la source de risque va probablement atteindre son objectif","Quasi certain : elle va certainement l'atteindre","Vraisemblable : elle est susceptible de l'atteindre","Peu vraisemblable : elle a peu de chance de l'atteindre"], a:[0], e:"<b>V4</b> quasi certain (va <b>certainement</b>) · <b>V3</b> très vraisemblable (va <b>probablement</b>) · <b>V2</b> vraisemblable (est <b>susceptible</b>) · <b>V1</b> peu vraisemblable (a <b>peu de chance</b>)."},
{id:"B26", ch:25, d:3, q:"La gravité d'un scénario opérationnel, comment se détermine-t-elle&nbsp;?", o:["Elle est celle du scénario stratégique associé, évaluée à l'atelier 3 — on ne la réévalue pas","Elle se recalcule à partir des actions élémentaires","Elle se déduit de la vraisemblance","Elle est fixée à l'atelier 5"], a:[0], e:"Le guide le rappelle explicitement. Il suggère aussi de <b>rapprocher la vraisemblance de la pertinence du couple SR/OV</b> associé, pour vérifier la cohérence entre les deux."},
{id:"B27", ch:25, d:2, q:"Pourquoi le guide insiste-t-il sur l'<b>enchaînement</b> d'actions plutôt que sur des vulnérabilités isolées&nbsp;?", o:["Parce qu'une attaque réussie exploite plusieurs failles, dont chacune peut sembler anodine lorsqu'on la considère individuellement","Parce que les vulnérabilités isolées sont rares","Parce que les scanners ne détectent pas les vulnérabilités isolées","Parce que la norme l'impose"], a:[0], e:"La démarche doit permettre d'identifier les <b>biens supports critiques</b> susceptibles de servir de <b>vecteur d'entrée</b>, d'<b>exploitation</b> ou de <b>relais de propagation</b>."},

/* ---- Ch. 26 : atelier 5 ---- */
{id:"B28", ch:26, d:1, q:"Quelles sont les <b>quatre données de sortie</b> de l'atelier 5&nbsp;?", o:["La stratégie de traitement du risque ; la synthèse des risques résiduels ; le plan de traitement du risque ; le cadre du suivi des risques","Les scénarios de risque et leur cotation","Le socle de sécurité et ses écarts","La cartographie des sources de risque"], a:[0], e:"Les participants sont <b>les mêmes qu'à l'atelier 1</b> — Direction, Métiers, RSSI, DSI : ceux qui ont cadré décident du traitement."},
{id:"B29", ch:26, d:2, q:"Quelles sont les <b>trois classes d'acceptabilité</b> du risque&nbsp;?", o:["Acceptable en l'état (aucune action) · tolérable sous contrôle (suivi et amélioration continue) · inacceptable (mesures impératives à court terme)","Faible · moyen · élevé · critique","Éviter · réduire · transférer · accepter","Vert · orange · rouge"], a:[0], e:"En cas de risque <b>inacceptable</b> non traité, le guide est net : «&nbsp;<b>tout ou partie de l'activité sera refusé</b>&nbsp;». La stratégie de traitement «&nbsp;formalise les <b>seuils d'acceptation</b> et un <b>niveau de sécurité à atteindre</b> en cas de non-acceptation&nbsp;»."},
{id:"B30", ch:26, d:2, q:"Qu'est-ce qu'un <b>risque résiduel</b>&nbsp;?", o:["Le scénario de risque subsistant après application de la stratégie de traitement, réévalué en gravité et vraisemblance","Le risque qu'on a décidé d'ignorer","Le risque porté par l'écosystème","Le risque non identifié lors de l'appréciation"], a:[0], e:"Par opposition au <b>risque initial</b>, évalué <b>avant</b> application de la stratégie. Les deux s'évaluent sur les <b>mêmes axes</b> : gravité et vraisemblance."},
{id:"B31", ch:26, d:3, q:"Quel contrôle le guide recommande-t-il pour éviter les <b>angles morts</b> à l'atelier 5&nbsp;?", o:["Passer en revue tous les événements redoutés de l'atelier 1 et identifier ceux qu'aucun scénario de risque n'a abordés — au besoin via une matrice de couverture","Recompter les biens supports","Vérifier que chaque mesure a un budget","Auditer le socle une seconde fois"], a:[0], e:"Selon leur gravité, on peut alors décider de <b>refaire une itération des ateliers 2, 3 et 4</b>. C'est exactement le type de contrôle qui démontre la <b>cohérence de l'enchaînement</b>."},
{id:"B32", ch:26, d:2, q:"Sur quoi une <b>mesure de sécurité</b> peut-elle agir, selon le guide&nbsp;?", o:["Sur une valeur métier, un bien support, ou une partie prenante de l'écosystème","Sur les biens supports uniquement","Sur les sources de risque","Sur les événements redoutés uniquement"], a:[0], e:"Elle peut être <b>fonctionnelle, technique ou organisationnelle</b>, et prendre «&nbsp;la forme de <b>solutions ou d'exigences pouvant être inscrites dans un contrat</b>&nbsp;». Certaines se <b>renforcent mutuellement</b> selon quatre axes : <b>gouvernance, protection, défense, résilience</b>."},
{id:"B33", ch:26, d:3, q:"Qu'est-ce que l'<b>homologation de sécurité</b>&nbsp;?", o:["La validation, par une autorité d'homologation, que le niveau de sécurité atteint est conforme aux attentes et que les risques résiduels sont acceptés","La certification d'un produit par un organisme accrédité","L'obtention d'une attestation ISO 27001","L'accord de l'ANSSI sur une architecture"], a:[0], e:"C'est l'un des trois usages annoncés d'EBIOS RM. Le repère : on <b>certifie un produit</b>, on <b>homologue un système</b>."},

/* ---- Ch. 27 : adapter et conduire ---- */
{id:"B34", ch:27, d:2, q:"Pour évaluer le <b>niveau de menace de l'écosystème</b> seul, quel atelier suffit&nbsp;?", o:["L'atelier 3, étape (A) uniquement — sans avoir conduit les ateliers 1 et 2","L'atelier 1","Les ateliers 1, 2 et 3","Les cinq ateliers"], a:[0], e:"EBIOS RM est «&nbsp;une véritable <b>boîte à outils</b>&nbsp;» dont on adapte le niveau de détail et le séquencement. Pour <b>orienter un audit ou un test d'intrusion</b>, ce sont les ateliers <b>3 et 4</b> ; pour une <b>étude complète en vue d'une homologation</b>, les <b>cinq</b>."},

/* ---- Série C : apports de l'oral de la journée 1 (quatre transcriptions) ---- */
{id:"C01", ch:1, d:2, q:"Quel exemple le cours donne-t-il d'une <b>norme utilisée directement comme méthode</b>&nbsp;?", o:["La banque et la finance appliquent l'ISO 27005 comme méthode d'analyse de risque, au lieu d'EBIOS RM","L'industrie automobile applique l'ISO 21434 au lieu du NIST CSF","Les administrations appliquent l'ISO 27001 au lieu de la PSSIE","Les hébergeurs appliquent l'ISO 27002 au lieu d'ITIL"], a:[0], e:"C'est l'illustration de la <b>porosité</b> entre cadre normatif et cadre méthodologique. Dans l'autre sens, une <b>loi a souvent d'abord été une norme</b>&nbsp;: quand celle-ci s'impose mondialement, le législateur peut lui donner force obligatoire."},
{id:"C02", ch:1, d:1, q:"Être certifié <b>ISO 27001</b> est-il une obligation légale&nbsp;?", o:["Non : rien ne vous oblige légalement — c'est un argument commercial majeur, une exigence du marché, pas du droit","Oui, pour toute entreprise de plus de 250 salariés","Oui, pour tout opérateur de services essentiels au titre de NIS 2","Non, sauf pour les prestataires de l'État"], a:[0], e:"«&nbsp;La norme n'est pas une loi.&nbsp;» Mais entre deux prestataires, le client choisira celui qui est certifié ou labellisé ANSSI. C'est la distinction fondamentale entre le <b>cadre réglementaire</b> — impératif — et le <b>cadre normatif</b> — consensuel."},
{id:"C03", ch:1, d:2, q:"Dans la classification Défense, que déclenche le classement d'un équipement en <b>C3</b>&nbsp;?", o:["Une analyse de risque exhaustive devient une obligation légale : plus de 60 pages, contre quelques pages pour une analyse de conformité","Une interdiction totale de connexion à un réseau externe","Une obligation de certification ISO 27001 du site","Une revue mensuelle par l'ANSSI"], a:[0], e:"Les trois classes&nbsp;: <b>C1</b> faiblement critique (détection incendie), <b>C2</b> moyennement critique (téléphonie sur IP), <b>C3</b> très critique. Sur un C3, les trois cadres se superposent&nbsp;: l'<b>obligation</b> impose, l'<b>ISO 27005</b> structure, <b>EBIOS RM</b> instancie."},
{id:"C04", ch:2, d:2, q:"Le <b>consensus</b> qui gouverne la normalisation signifie-t-il l'unanimité&nbsp;?", o:["Non : c'est une très large majorité d'experts, de l'ordre de 90 %","Oui, l'unanimité des membres du comité technique est requise","Oui, mais seuls les membres permanents votent","Non : une majorité simple suffit"], a:[0], e:"L'autre caractéristique fondamentale est la <b>reproductibilité</b>&nbsp;: «&nbsp;sans protocole reproductible, une norme n'a aucune valeur.&nbsp;» La transcription signale qu'une <b>question récurrente d'examen</b> serait&nbsp;: <i>donnez-moi deux principes qui gouvernent le processus de normalisation</i> — mais ce passage est rédigé à la <b>troisième personne</b> par l'outil de transcription, sans horodatage de parole&nbsp;: ce ne sont pas les mots de l'enseignant."},
{id:"C05", ch:3, d:2, q:"Dans la <b>matrice RACI</b> appliquée à une crise cyber, qui est le <b>C</b>&nbsp;?", o:["Le consulté : l'architecte sécurité ou le juriste, qu'il est obligatoire de consulter avant la décision","Le coordinateur de crise","Le client, tenu informé des actions","Le contrôleur, qui audite après coup"], a:[0], e:"<b>R</b> responsable-décideur (le RSSI) · <b>A</b> acteur-exécutant (l'administrateur) · <b>C</b> consulté · <b>I</b> informé (le DSI, la direction). Attention au <b>faux-ami</b>&nbsp;: en anglais <i>Responsible</i> est celui qui exécute et <i>Accountable</i> celui qui décide — l'usage français inverse souvent les deux."},
{id:"C06", ch:4, d:2, q:"Que prévoit l'<b>AI Act</b> dès <b>août 2024</b> pour les éditeurs de contenus&nbsp;?", o:["Apposer la mention contenu généré par IA, sauf si l'article a été entièrement relu et validé par un humain qui en assume les propos","Déclarer chaque modèle d'IA utilisé auprès de l'ENISA","Conserver les journaux de génération pendant cinq ans","Interdire tout usage d'IA générative pour les contenus d'actualité"], a:[0], e:"À l'horizon <b>2028</b>, l'obligation se déplacera vers les <b>fournisseurs d'IA</b> eux-mêmes, avec des <b>filigranes indélébiles</b> dans les images, vidéos et textes générés. Le défi technique de l'exception&nbsp;: prouver la relecture humaine, d'où les pistes de sceaux numériques et d'horodatage certifié."},
{id:"C07", ch:4, d:3, q:"Quelle est la différence entre <b>ISO/IEC 42001</b> et <b>ISO/IEC 23894</b>&nbsp;?", o:["La 42001 traite du risque intrinsèque de l'IA (défaillances, cygnes noirs), la 23894 des risques sociétaux et des préjudices aux tiers (biais, santé mentale)","La 42001 est européenne, la 23894 est internationale","La 42001 est certifiable, la 23894 ne l'est pas","La 42001 vise les fournisseurs, la 23894 les utilisateurs"], a:[0], e:"Moyen mnémotechnique&nbsp;: la <b>42001 regarde vers l'intérieur</b> du système — ce qui peut mal fonctionner&nbsp;; la <b>23894 regarde vers la société</b> — qui peut être lésé. Les deux sont les pendants normatifs de l'<b>AI Act</b>."},
{id:"C08", ch:6, d:1, q:"Quelle doit <b>toujours</b> être la première question face à une entreprise qui annonce sa certification ISO 27001&nbsp;?", o:["« Quel est le périmètre exact de votre certification ? »","« Quel organisme vous a certifié ? »","« Depuis quelle date êtes-vous certifié ? »","« Combien de non-conformités ont été relevées ? »"], a:[0], e:"Présenté comme «&nbsp;le piège absolu&nbsp;». Une organisation peut faire certifier <b>un seul petit service</b> puis communiquer comme si tout l'était. Pire&nbsp;: une entreprise aux systèmes archaïques peut monter un <b>micro-SMSI exemplaire</b> sur un service annexe et s'en servir de <b>leurre commercial</b>."},
{id:"C09", ch:6, d:2, q:"Quelle est la <b>durée de validité</b> d'une certification ISO 27001, et quel suivi l'accompagne&nbsp;?", o:["Trois ans, avec des audits de surveillance annuels","Cinq ans, avec un audit à mi-parcours","Un an, renouvelable par simple déclaration","Trois ans, sans suivi intermédiaire"], a:[0], e:"À retenir avec l'autre précision du cours sur le PDCA&nbsp;: «&nbsp;en anglais c'est <i>Act</i>, en français on devrait plutôt dire <b>Réagir</b>&nbsp;» — c'est l'étape où l'on corrige les écarts constatés au <i>Check</i>."},
{id:"C11", ch:7, d:2, q:"Quel exemple le cours donne-t-il d'une donnée <b>sensible qui n'est pas personnelle</b>&nbsp;?", o:["La formule secrète du Coca-Cola, un code source propriétaire, un brevet non publié, une clé cryptographique privée","Le numéro de sécurité sociale d'un salarié","L'adresse postale d'un client","Les données de santé d'un patient"], a:[0], e:"Et l'inverse — <b>personnelle mais pas sensible</b>&nbsp;: les informations publiques d'une personnalité sur Wikipédia, ou la <b>déclaration publique de patrimoine</b> d'un candidat à la présidentielle. Les deux notions se croisent sans se recouvrir."},
{id:"C12", ch:7, d:2, q:"Quel document un auditeur exige-t-il pour vérifier l'organisation des rôles et des accès&nbsp;?", o:["La matrice RBAC — un tableau à double entrée profils / droits sur chaque ressource","Le registre des traitements RGPD","Le plan de continuité d'activité","La cartographie applicative"], a:[0], e:"«&nbsp;Si l'entreprise n'est pas capable de la fournir, c'est une <b>non-conformité majeure</b>.&nbsp;» L'autre document exigé est la <b>CMDB</b>&nbsp;: pas seulement la liste des serveurs, mais les <b>versions de build</b>, les <b>numéros de correctifs</b> et les <b>licences logicielles</b>."},
{id:"C13", ch:9, d:1, q:"Comment s'appelle correctement le modèle qui illustre la limite de la défense en profondeur&nbsp;?", o:["Le modèle du fromage suisse de James Reason — l'emmental, car le gruyère n'a pas de trous","Le modèle du gruyère de James Reason","Le modèle de l'oignon de Bruce Schneier","Le modèle des couches de Vauban"], a:[0], e:"Plusieurs tranches trouées superposées&nbsp;: «&nbsp;si vous laissez un peu de temps à l'attaquant, il finira par trouver les trous dans chaque tranche&nbsp;» et les alignements se produisent. La défense en profondeur <b>achète du temps</b>, elle ne supprime pas le risque."},
{id:"C14", ch:9, d:2, q:"Dans un arbitrage entre le RSSI et le directeur de production sur un serveur industriel obsolète, qui l'emporte, selon le cours&nbsp;?", o:["Dans 99 % des cas en milieu industriel, c'est la production qui gagne sur la sécurité — le RSSI propose alors des mesures compensatoires","Le RSSI, car la vulnérabilité engage sa responsabilité","La direction générale tranche systématiquement","L'arbitrage remonte à l'ANSSI pour les OIV"], a:[0], e:"L'impératif est la <b>disponibilité opérationnelle</b>&nbsp;: «&nbsp;si le système n'a plus de vulnérabilité mais que l'usine ne produit plus rien, l'entreprise meurt.&nbsp;» Les mesures compensatoires citées&nbsp;: isoler la machine dans un <b>VLAN hermétique</b> sans accès Internet, restreindre les accès physiques, filtrer les flux."},
{id:"C15", ch:10, d:2, q:"Quelle différence le cours établit-il entre la <b>CTI</b> et le <b>Threat Hunting</b>&nbsp;?", o:["La CTI est souvent post-mortem — attaques passées, signatures, IoC ; le Threat Hunting porte sur des attaques en cours","La CTI est automatisée, le Threat Hunting est manuel","La CTI est stratégique, le Threat Hunting est réglementaire","La CTI vise les malwares, le Threat Hunting les intrusions physiques"], a:[0], e:"Le Threat Hunting est «&nbsp;une traque proactive menée par des analystes qui cherchent les anomalies discrètes <b>sans attendre une alerte automatique</b>&nbsp;». Repère temporel&nbsp;: <b>la CTI regarde hier, le Threat Hunting regarde maintenant</b>."},
{id:"C16", ch:10, d:3, q:"Quelle analogie le cours utilise-t-il pour fixer la limite juridique de la déception <b>mimétique</b>&nbsp;?", o:["Camoufler un char en forêt est licite ; peindre une fausse croix rouge pour le déguiser en ambulance est interdit par les conventions de Genève","Poser un piège à loup est licite, poser une mine ne l'est pas","Écouter une conversation publique est licite, la retranscrire ne l'est pas","Filmer la voie publique est licite, filmer un domicile ne l'est pas"], a:[0], e:"La <b>déception cryptique</b> — chiffrer, brouiller, stéganographie — est «&nbsp;légitime et universellement licite&nbsp;». La <b>mimétique</b> — faux serveurs, faux comptes, <b>honeypots</b> — est autorisée en défense, mais pas si elle <b>incite au crime</b>."},
{id:"C17", ch:12, d:2, q:"Quelles sont les <b>trois dates</b> de l'histoire du zero trust données en cours&nbsp;?", o:["1994 Marsh (Stirling) · 2010 Kindervag (Forrester) · 2020 NIST SP 800-207","1994 Kindervag · 2010 NIST · 2019 Gartner","2003 Jericho Forum · 2010 Forrester · 2014 Google BeyondCorp","2010 Stuxnet · 2019 Gartner · 2022 ANSSI"], a:[0], e:"Marsh a formalisé la <b>confiance comme variable calculable</b>&nbsp;; Kindervag a <b>nommé</b> le modèle — d'où le couplage <b>zero trust → Forrester</b>&nbsp;; le NIST l'a <b>normalisé</b>. À rapprocher de <b>Stuxnet (2010)</b>, «&nbsp;la première cyber-arme physique de l'histoire&nbsp;», qui a saboté les centrifugeuses de Natanz."},
{id:"C18", ch:15, d:2, q:"Que se passe-t-il si un poste n'a pas appliqué le dernier correctif, alors que mot de passe et MFA sont corrects&nbsp;?", o:["L'accès est immédiatement refusé : l'état de santé du terminal est un signal du policy engine au même titre que l'identité","L'accès est accordé mais journalisé comme anormal","L'accès est accordé en lecture seule","Une validation manuelle d'un administrateur est demandée"], a:[0], e:"C'est la démonstration que le <b>terminal</b> est une <b>entrée de la décision</b>, et pas seulement l'utilisateur. Les autres signaux&nbsp;: <b>géolocalisation anormale</b>, <b>heure inhabituelle</b>, <b>analyse comportementale (UEBA)</b> et <b>besoin d'en connaître</b>."},
{id:"C19", ch:15, d:2, q:"Quelle est la limite du <b>RBAC</b> que l'<b>ABAC</b> vient corriger&nbsp;?", o:["Si le compte du rôle est volé, l'attaquant obtient tous les droits du rôle ; en ABAC, l'accès est bloqué si le contexte ne correspond pas","Le RBAC ne gère pas les comptes de service","Le RBAC est incompatible avec le SSO","Le RBAC ne fonctionne qu'en environnement Windows"], a:[0], e:"Les <b>quatre familles d'attributs</b> de l'ABAC&nbsp;: <b>utilisateur</b>, <b>ressource</b>, <b>appareil</b>, <b>environnement</b> — ce sont les entrées du PEP vues côté décision. Le <b>RuBAC</b> est l'intermédiaire&nbsp;: des règles conditionnelles, mais pas encore d'attributs dynamiques."},
{id:"C20", ch:13, d:3, q:"Sur le <b>troisième principe</b> du zero trust, que disent respectivement le support et le cours oral&nbsp;?", o:["Le support dit surveillance continue ; le cours oral dit présumer la compromission (assume breach)","Les deux disent surveillance continue","Les deux disent assume breach","Le support dit assume breach, le cours dit surveillance continue"], a:[0], e:"Les <b>deux premiers principes sont identiques</b> dans les deux versions. Dans le support, <i>assume breach</i> est une <b>précision du premier</b> principe&nbsp;; dans le cours, c'est le <b>troisième</b> — c'est la formulation de Microsoft. Les deux circulent réellement&nbsp;: il faut connaître les deux."},

/* ---- Série D : séance 2 — notion de risque, ISO 27005, EBIOS RM ---- */
{id:"D01", ch:11, d:1, q:"Quelle est la différence entre un <b>danger</b> et un <b>risque</b>&nbsp;?", o:["Le danger est une propriété intrinsèque ; le risque est une situation d'exposition à ce danger","Le danger est potentiel, le risque est avéré","Le danger est externe, le risque est interne","Le danger concerne les personnes, le risque concerne les biens"], a:[0], e:"L'exemple du verglas&nbsp;: la plaque est le <b>danger</b> — un fait physique. <b>Tant que personne ne passe à proximité, il n'y a aucun risque.</b> Le risque naît de l'exposition. Et la fracture est le <b>dommage</b>. Le risque n'est donc pas une propriété du système."},
{id:"D02", ch:11, d:2, q:"Quelle est la <b>norme mère</b> internationale en matière de gestion des risques&nbsp;?", o:["L'ISO 31000 — l'ISO 27005 n'en est que la déclinaison pour la sécurité de l'information","L'ISO 27005, dont l'ISO 31000 est une annexe","L'ISO 27001, qui couvre tous les types de risques","L'ISO 9001, dont dérivent toutes les normes de management"], a:[0], e:"Erreur d'aiguillage classique. L'<b>ISO 31000</b> s'applique à tous les secteurs&nbsp;: risque financier (la dette souveraine grecque), industriel (les microfissures des cuves EDF), médical (la vaccination)."},
{id:"D03", ch:11, d:1, q:"Comment se décompose la <b>vraisemblance</b>&nbsp;?", o:["Vraisemblance = Menace × Vulnérabilité","Vraisemblance = Gravité × Impact","Vraisemblance = Exposition × Criticité","Vraisemblance = Fréquence × Durée"], a:[0], e:"Et au second niveau&nbsp;: la <b>menace</b> = <b>attractivité de la cible</b> + <b>vecteur d'accès</b>&nbsp;; la <b>vulnérabilité</b> = <b>vulnérabilités intrinsèques</b> (CVE, obsolescence) + <b>complexité de l'attaque</b> (longueur de la kill chain). Le risque, lui, est fonction de la <b>gravité</b> et de la <b>vraisemblance</b>."},
{id:"D04", ch:11, d:2, q:"Pourquoi utilise-t-on une échelle de cotation à <b>4 niveaux</b> plutôt qu'à 3 ou 5&nbsp;?", o:["Pour éliminer le biais cognitif du juste milieu : une échelle paire force à trancher","Parce que la matrice cartésienne exige un nombre pair de cases","Parce que l'ISO 27005 l'impose formellement","Parce que quatre niveaux suffisent à couvrir tous les cas rencontrés"], a:[0], e:"Avec une échelle impaire, les participants ont «&nbsp;une tendance psychologique quasi systématique à choisir la valeur <b>centrale</b> pour ne pas se mouiller&nbsp;». Une échelle paire oblige à décider&nbsp;: plutôt mineur (1-2) ou plutôt majeur (3-4)."},
{id:"D05", ch:11, d:3, q:"La <b>capacité</b> et la <b>motivation</b> d'une source de risque relèvent de&nbsp;…", o:["la vraisemblance","la gravité","les deux à parts égales","ni l'une ni l'autre : c'est un critère de cadrage"], a:[0], e:"La règle mémotechnique&nbsp;: tout ce qui regarde <b>vers l'intérieur</b> de l'entreprise — actifs, données, préjudices, réputation, survie — c'est la <b>gravité</b>&nbsp;; tout ce qui regarde <b>vers l'extérieur et la technique</b> — attaquant, motivation, vecteur, failles, complexité — c'est la <b>vraisemblance</b>."},
{id:"D06", ch:11, d:2, q:"Que recouvre exactement l'<b>appréciation du risque</b> au sens de l'ISO 27005&nbsp;?", o:["Le terme englobant : identification, puis estimation, puis évaluation","Uniquement le calcul gravité × vraisemblance","Uniquement la confrontation aux critères d'acceptation","La phase qui suit le traitement du risque"], a:[0], e:"C'est l'articulation sur laquelle «&nbsp;les promotions précédentes ont souvent eu des difficultés&nbsp;». <b>Évaluer</b>, c'est précisément <b>confronter le niveau calculé aux critères d'acceptation</b> de l'entreprise, et trancher. Les quatre phases du processus&nbsp;: contexte, appréciation, traitement, acceptation du risque résiduel."},
{id:"D07", ch:11, d:2, q:"Combien de besoins de sécurité un <b>événement redouté</b> peut-il concerner&nbsp;?", o:["Un seul à la fois : la destruction d'une borne vise la disponibilité, l'écoute passive la confidentialité, l'altération l'intégrité — trois ER distincts","Tous ceux qui sont affectés par le même incident","Deux au maximum, pour rester lisible","Autant que nécessaire, sans limite"], a:[0], e:"Règle énoncée à l'identification. Les critères sont notés <b>DICP</b> en cours&nbsp;: <b>D</b>isponibilité, <b>I</b>ntégrité, <b>C</b>onfidentialité, <b>P</b>reuve. Un même incident produit donc <b>plusieurs</b> événements redoutés, un par critère atteint."},
{id:"D08", ch:11, d:1, q:"Quelles sont les <b>quatre stratégies</b> de traitement du risque&nbsp;?", o:["Maintien (acceptation) · refus (évitement) · réduction (mitigation) · transfert (partage)","Prévention · détection · correction · récupération","Identification · estimation · évaluation · acceptation","Éviter · réduire · assurer · documenter"], a:[0], e:"Le <b>maintien</b> exige une <b>validation signée par la direction générale</b>. Le <b>refus</b> supprime l'activité — l'exemple de <b>Rabobank</b>, qui a fermé sa filiale belge. La <b>réduction</b> est la plus fréquente. Le <b>transfert</b> passe par l'infogérance (OVHcloud, AWS) ou la <b>cyber-assurance</b>."},
{id:"D09", ch:11, d:2, q:"Que veut illustrer l'analogie de la <b>plaque d'égout ronde</b>&nbsp;?", o:["Le refus du risque par conception : une plaque ronde ne peut mathématiquement jamais tomber dans son trou","La réduction du risque par ajout de contre-mesures","Le transfert du risque vers le fabricant","L'acceptation d'un risque résiduel jugé tolérable"], a:[0], e:"Les plaques carrées, insérées en diagonale, pouvaient glisser dans le trou et provoquer des accidents mortels. Passer au rond <b>supprime le risque à la source</b>, plutôt que de le réduire ou de le surveiller."},
{id:"D10", ch:11, d:2, q:"Quelle est la <b>différence fondamentale</b> entre un audit de sécurité et une analyse de risque&nbsp;?", o:["L'audit exige obligatoirement un référentiel préexistant ; l'analyse de risque peut partir de zéro","L'audit est externe, l'analyse de risque est interne","L'audit est technique, l'analyse de risque est organisationnelle","L'audit est annuel, l'analyse de risque est ponctuelle"], a:[0], e:"Annoncé comme une <b>question d'entretien d'embauche</b>. L'audit est un travail de <b>conformité</b>&nbsp;: on compare la réalité à un document. L'analyse est un travail d'<b>investigation</b>. L'anecdote&nbsp;: une étudiante arrive chez <b>Thales</b> alors que le RSSI vient de démissionner — un audit aurait été bloqué, l'analyse a pu repartir de zéro par ateliers."},
{id:"D11", ch:11, d:3, q:"Quelles méthodes de gestion du risque sont nées en <b>1995</b>, et où&nbsp;?", o:["EBIOS (DCSSI) et MEHARI (CLUSIF) — deux réponses françaises concurrentes la même année","CRAMM au Royaume-Uni et OCTAVE aux États-Unis","MEHARI en France et NIST SP 800-30 aux États-Unis","EBIOS en France et CRAMM au Royaume-Uni"], a:[0], e:"Le panorama&nbsp;: <b>CRAMM</b> 1987 (Royaume-Uni, l'ancêtre de l'ISO 27000) · <b>EBIOS</b> et <b>MEHARI</b> 1995 (France) · <b>OCTAVE</b> 1999 (CERT/SEI) · <b>NIST SP 800-30</b> 2002 · <b>Cyber-PHA</b> pour l'industriel. MEHARI est privilégiée par les administrations, les collectivités et la <b>Défense / DGA</b>."},
{id:"D12", ch:11, d:2, q:"Quelle est la différence entre la <b>sécurité</b> (<i>security</i>) et la <b>sûreté</b> (<i>safety</i>)&nbsp;?", o:["La sécurité protège des actes intentionnels malveillants ; la sûreté, des défaillances accidentelles non intentionnelles","La sécurité est logique, la sûreté est physique","La sécurité concerne les données, la sûreté concerne les personnes","La sécurité est réglementaire, la sûreté est normative"], a:[0], e:"La conséquence méthodologique est ce qui compte&nbsp;: <b>EBIOS RM ne traite QUE de la sécurité</b>, c'est-à-dire de l'intentionnel. Pour les aléas de sûreté industrielle, il faut coupler avec l'<b>AMDEC</b> ou le <b>Cyber-PHA</b> (CEI 62443). Présenté comme une distinction «&nbsp;que vous devez impérativement maîtriser&nbsp;»."},
{id:"D13", ch:21, d:2, q:"Qu'est-ce qui oppose <b>EBIOS 2010</b> et <b>EBIOS Risk Manager</b> sur la philosophie d'analyse&nbsp;?", o:["EBIOS 2010 vise l'exhaustivité ; EBIOS RM vise la représentativité","EBIOS 2010 vise la représentativité ; EBIOS RM vise l'exhaustivité","Les deux visent l'exhaustivité, mais sur des périmètres différents","Les deux visent la représentativité, mais avec des échelles différentes"], a:[0], e:"Signalé comme «&nbsp;un <b>point capital à retenir pour vos examens</b>&nbsp;». Les autres oppositions&nbsp;: centre de gravité <b>SI</b> contre <b>métier</b>&nbsp;; menaces <b>unitaires</b> contre <b>scénarisées</b>&nbsp;; <b>ascendant</b> contre <b>descendant</b>&nbsp;; <b>5 modules</b> rigides contre <b>5 ateliers</b> agiles."},
{id:"D14", ch:21, d:2, q:"Quelle métaphore résume le changement de centre de gravité entre EBIOS 2010 et EBIOS RM&nbsp;?", o:["Le château fort et la princesse : peu importe que les murs tombent, ce qui compte est que le métier survive","Le fort de Vauban et l'emmental","La muraille de Chine et ses passages dérobés","Le triangle du feu et son extinction"], a:[0], e:"«&nbsp;Dans EBIOS 2010, on cherchait à défendre <b>les murs du château fort</b> (le SI). Dans EBIOS RM, on se fiche que les murs tombent&nbsp;: ce qui compte, c'est que <b>la princesse</b> — le processus métier vital — <b>survive</b>&nbsp;!&nbsp;» Les autres métaphores appartiennent à la séance 1."},
{id:"D15", ch:21, d:2, q:"EBIOS RM est-elle adaptée à une association de dix salariés&nbsp;?", o:["Non : un rouleau compresseur surdimensionné. Il faut lui préférer le guide d'hygiène de l'ANSSI ou une démarche ISO 27005 simplifiée","Oui, en se limitant aux ateliers 1 et 5","Oui, c'est précisément sa cible depuis la version 2018","Non, mais uniquement pour des raisons de coût de licence des outils"], a:[0], e:"EBIOS RM vise les <b>grandes entreprises, les OIV et les systèmes critiques</b>. Le type de traitement des petites structures relève des <b>étages 1 et 2</b> de la pyramide — hygiène et conformité — que la méthode considère justement comme un <b>prérequis</b>."},
{id:"D16", ch:21, d:1, q:"Quel outil labellisé sert aux travaux pratiques du module&nbsp;?", o:["Agile Risk Manager, édité par AllForTech / Olfeo","Egerie Risk Manager","RSA Archer","Famic, d'Airbus Defence and Space"], a:[0], e:"Décrit comme «&nbsp;de loin l'un des meilleurs du marché&nbsp;», en SaaS sur le VPS de l'école. <b>Egerie</b> a décliné la collaboration&nbsp;; <b>Famic</b> est réservé aux filières spatiales et défense&nbsp;; <b>RSA Archer</b> est «&nbsp;hors de prix&nbsp;». La labellisation ANSSI garantit l'implémentation fidèle des <b>5 ateliers</b> et la conformité à l'<b>ISO 27005</b>."},
{id:"D17", ch:22, d:3, q:"Lequel de ces référentiels <b>n'entre pas</b> dans le socle de sécurité d'une analyse EBIOS RM&nbsp;?", o:["L'IGI 1300 — protection du secret de la défense nationale","La PSSI de l'entreprise","Le guide d'hygiène informatique de l'ANSSI","La LPM, pour un opérateur d'importance vitale"], a:[0], e:"L'IGI 1300 relève de la protection du secret d'État, «&nbsp;qui s'impose aux <b>personnes physiques accréditées</b> et aux <b>locaux classifiés</b>, et non au système d'information bureautique standard&nbsp;». Le critère de tri&nbsp;: le socle rassemble les référentiels <b>applicables au SI</b>. RGPD, annexe A de l'ISO 27001 et code de la santé publique en font partie."},
{id:"D18", ch:25, d:2, q:"À la fin de quel atelier détermine-t-on la <b>vraisemblance</b>&nbsp;?", o:["L'atelier 4 — scénarios opérationnels ; croisée avec la gravité de l'atelier 1, elle donne la matrice finale des risques","L'atelier 1, en même temps que la gravité","L'atelier 3, à l'issue des scénarios stratégiques","L'atelier 5, au moment du traitement"], a:[0], e:"C'est le résultat capital de l'atelier 4. La <b>gravité</b> vient de l'atelier 1 (événements redoutés), la <b>vraisemblance</b> de l'atelier 4 (chemins d'attaque). L'atelier 4 est aussi le plus technique&nbsp;: <b>MITRE ATT&amp;CK</b>, <b>CAPEC</b>, et seuls le RSSI et les experts y participent — les métiers sont libérés."},
{id:"D19", ch:11, d:3, q:"D'où vient la modélisation mathématique du risque&nbsp;?", o:["De Christiaan Huygens (1659), formalisée par Daniel Bernoulli (1738) : le risque comme espérance mathématique du dommage","De Blaise Pascal et Pierre de Fermat, en 1654","De Thomas Bayes, en 1763","D'Andreï Kolmogorov, en 1933"], a:[0], e:"Le risque y est défini comme «&nbsp;la valeur moyenne des conséquences d'événements affectés à leur probabilité d'occurrence&nbsp;». C'est la justification théorique du produit <b>gravité × vraisemblance</b>."},
{id:"D20", ch:11, d:2, q:"Quelles sont les <b>trois catégories de parties prenantes</b> analysées dans l'écosystème&nbsp;?", o:["Les clients, les partenaires, les fournisseurs et sous-traitants","Les actionnaires, les salariés, les clients","Les métiers, la DSI, la direction générale","Les autorités, les assureurs, les prestataires"], a:[0], e:"Le troisième est «&nbsp;le <b>vecteur d'attaque le plus redoutable aujourd'hui</b>&nbsp;»&nbsp;: l'assaillant cible un petit sous-traitant mal sécurisé pour rebondir vers le donneur d'ordre. Exemples cités&nbsp;: le prestataire de climatisation chez <b>Target</b>, et <b>SolarWinds</b>."},

/* ---- Série F : supports corrigés (MethodoSecu1 rév.) et MethodoSecu2 ---- */
{id:"F02", ch:7, d:3, q:"Quelle mesure figure dans les «&nbsp;<b>autres réponses possibles</b>&nbsp;» du support, alors qu'elle avait été retenue à l'oral&nbsp;?", o:["<code>05.09</code> Inventaire des informations et des autres actifs associés","<code>08.12</code> Prévention de la fuite de données","<code>08.20</code> Mesures liées aux réseaux","<code>07.03</code> Sécurisation des bureaux et des équipements"], a:[0], e:"C'est la démonstration que les deux corrections sont compatibles&nbsp;: ce que l'oral a retenu dans les dix, l'écrit le range dans les alternatives acceptables. Les trois autres mesures citées figurent, elles, dans <b>les deux</b> listes de dix."},
{id:"F03", ch:11, d:3, q:"Un audit de sécurité vous remet une liste de constats. Qu'en fait l'analyste de risque&nbsp;?", o:["Il les prend comme point de départ et déduit de l'architecture ce que l'audit ne dit pas","Il s'en tient strictement aux constats : c'est la seule base factuelle disponible","Il les écarte tant qu'ils ne sont pas reproduits en test d'intrusion","Il les convertit directement en mesures, sans passer par les scénarios"], a:[0], e:"Un audit livre des <b>constats ponctuels</b>&nbsp;; il ne dit rien de ce qu'il n'a pas regardé. Un réseau plat sans cloisonnement interne et sans journalisation centralisée porte ces manques <b>par construction</b>, même si personne ne les a relevés. Savoir compléter un audit par la lecture de l'architecture est exactement ce qui distingue une analyse de risque d'un simple relevé de non-conformités."},
{id:"F06", ch:21, d:2, q:"Selon le <b>premier commandement</b> d'EBIOS RM, comment les risques non délibérés sont-ils traités&nbsp;?", o:["Par l'analyse de conformité, qui identifie des écarts — sans être modélisés en scénarios","Par des scénarios opérationnels simplifiés à l'atelier 4","Ils sont exclus du périmètre de la méthode","Par un atelier 6 optionnel dédié à l'accidentel"], a:[0], e:"Nuance à connaître&nbsp;: EBIOS RM permet de gérer <b>tous les risques numériques</b> — attaques ciblées, accidents, non humains. Dire qu'elle «&nbsp;ignore l'accidentel&nbsp;» est trop fort&nbsp;: elle ne le <b>modélise</b> pas, elle le traite par le <b>socle</b>."},
{id:"F07", ch:21, d:2, q:"Quels sont les <b>quatre critères</b> de cotation de la menace des parties prenantes&nbsp;?", o:["Dépendance, pénétration, maturité cyber, confiance","Motivation, ressources, activité, pertinence","Gravité, vraisemblance, exposition, criticité","Disponibilité, intégrité, confidentialité, preuve"], a:[0], e:"Septième commandement. On recherche une <b>évaluation relative</b> de la menace, pour identifier les parties prenantes <b>les plus menaçantes</b>. Motivation, ressources et activité sont les critères d'évaluation des <b>couples SR/OV</b> à l'atelier 2&nbsp;: ils portent sur la <b>source</b>, pas sur la partie prenante."},
{id:"F08", ch:21, d:3, q:"Selon le <b>dixième commandement</b>, d'où proviennent les mesures de traitement&nbsp;?", o:["De la réflexion de chaque atelier — et non uniquement des ateliers 3 ou 4","Exclusivement de l'atelier 5, qui les définit","Exclusivement du socle de sécurité de l'atelier 1","Des référentiels ISO 27002 appliqués au périmètre"], a:[0], e:"Les mesures <b>ne naissent pas</b> à l'atelier 5&nbsp;: elles y sont <b>consolidées</b>. L'atelier 3 produit déjà des mesures pour l'écosystème&nbsp;; l'atelier 1 identifie les écarts au socle."},
{id:"F09", ch:21, d:1, q:"Quel est l'objectif de l'<b>approche « Flash »</b>&nbsp;?", o:["Réaliser l'analyse de risques en mobilisant les acteurs pendant 2 à 3 heures","Automatiser l'analyse à l'aide d'un outil labellisé","Réaliser une analyse en une journée avec tous les métiers","Produire une analyse sans réunir de parties prenantes"], a:[0], e:"C'est la réponse à la critique d'EBIOS RM en petite structure&nbsp;: on ne renonce pas à la méthode, on en <b>comprime le format</b>. Bénéfices&nbsp;: adhésion du métier, identification des risques les plus importants, priorisation des mesures."},
{id:"F10", ch:28, d:1, q:"Quelles sont les <b>trois familles de risques liés à l'IA</b>&nbsp;?", o:["L'IA comme cible ou vecteur d'attaque · les risques intrinsèques · les risques causés à des tiers","Technique, organisationnel, juridique","Conception, entraînement, exploitation","Confidentialité, intégrité, disponibilité"], a:[0], e:"Et le constat qui les accompagne&nbsp;: «&nbsp;<b>aucune méthode unique ne permet aujourd'hui de couvrir correctement ces trois familles</b>&nbsp;». C'est le fil conducteur de toute la partie 3 du support."},
{id:"F11", ch:28, d:2, q:"Pourquoi EBIOS RM ne peut-elle pas traiter les <b>risques intrinsèques</b> de l'IA&nbsp;?", o:["Parce qu'elle repose sur le couple source de risque / objectif visé : sans attaquant, l'atelier 2 devient inapplicable","Parce qu'elle ne sait pas coter un préjudice algorithmique","Parce que l'IA n'a pas de biens supports identifiables","Parce qu'elle est réservée aux systèmes d'information classiques"], a:[0], e:"«&nbsp;EBIOS <b>ne comporte pas de notion d'erreur intrinsèque</b> (non intentionnelle) d'un système.&nbsp;» C'est la même limite que celle qui lui fait exclure la <b>sûreté</b> (<i>safety</i>)&nbsp;: pas d'attaquant, pas de scénario."},
{id:"F12", ch:28, d:2, q:"Quelle norme joue pour l'IA le rôle de l'<b>ISO 27001</b>&nbsp;?", o:["L'ISO/IEC 42001, qui définit le système de management de l'IA (AIMS)","L'ISO/IEC 23894, qui gère les risques liés à l'IA","L'ISO/IEC 42005, qui évalue les impacts sur les tiers","Le NIST AI RMF"], a:[0], e:"Son rôle&nbsp;: «&nbsp;<b>mettre sous contrôle</b> l'utilisation de l'IA dans l'organisation&nbsp;». Elle impose d'identifier, évaluer, traiter et suivre les risques, <b>mais ne prescrit aucune méthode</b> d'analyse — c'est l'<b>ISO 23894</b> qui joue ce rôle, en pendant de l'ISO 27005."},
{id:"F13", ch:28, d:3, q:"Quelle <b>inversion de perspective</b> HUDERIA opère-t-elle&nbsp;?", o:["EBIOS RM protège les valeurs métier de l'organisation ; HUDERIA évalue le préjudice que l'organisation peut faire subir aux droits humains, à la démocratie et à l'État de droit","EBIOS RM est qualitative, HUDERIA est quantitative","EBIOS RM traite l'intentionnel, HUDERIA l'accidentel","EBIOS RM vise le privé, HUDERIA le secteur public"], a:[0], e:"C'est la phrase de synthèse du support. HUDERIA vient du <b>Conseil de l'Europe</b> (2024), est complétée par le modèle <b>COBRA</b> (2026) et reste <b>non contraignante</b>&nbsp;: elle soutient la Convention-cadre sur l'IA."},
{id:"F14", ch:28, d:2, q:"Quelle est la question centrale de l'<b>ISO/IEC 42005</b>&nbsp;?", o:["« Qui pourrait être affecté par cette IA, et comment ? »","« Quel est notre niveau de maturité en gouvernance IA ? »","« Quelles sources de risque visent notre modèle ? »","« Le modèle est-il conforme à l'AI Act ? »"], a:[0], e:"Sa démarche en cinq étapes&nbsp;: identifier les <b>parties prenantes</b> · identifier les <b>impacts possibles</b> · évaluer leur <b>gravité</b> · définir des <b>mesures de réduction</b> · <b>documenter les arbitrages</b>. Elle se rapproche d'une <b>AIPD</b> plus que d'une analyse de risque cyber."},
{id:"F15", ch:26, d:2, q:"Comment le <b>support du cours</b> nomme-t-il le plan des mesures de l'atelier 5&nbsp;?", o:["Le PACS — plan d'amélioration continue de la sécurité","Le plan de traitement du risque","Le plan d'action correctif","Le référentiel des mesures retenues"], a:[0], e:"La diapositive 75 s'intitule «&nbsp;Atelier 5 — Traitement du risque <b>et PACS</b>&nbsp;». Le <b>guide ANSSI v1.5</b>, lui, l'a renommé <b>plan de traitement du risque</b>. Les deux désignent la même chose&nbsp;: retenez le terme du <b>support</b> si la question vient du cours."},

/* ---------- issues du QCM d'attestation EBIOS RM (40 questions, 16/09) ------ */
{id:"G01", ch:21, d:1, q:"Sur quel périmètre la méthode EBIOS RM s'applique-t-elle&nbsp;?", o:["Une entreprise, un système d'information ou un système industriel — les trois","Une entreprise uniquement","Un système d'information uniquement","Un système industriel uniquement"], a:[0], e:"Aucune des trois restrictions n'est vraie. C'est ce qui permet d'appliquer la méthode à un périmètre <b>OT</b> aussi bien qu'à un SI de gestion — et ce qui la distingue d'une méthode purement informatique."},
{id:"G02", ch:21, d:2, q:"Que propose d'identifier la méthode EBIOS RM&nbsp;?", o:["Les risques cyber les plus représentatifs sur le périmètre identifié","L'ensemble des risques cyber sur le périmètre identifié","Les risques spécifiques aux données personnelles","Les risques cyber, sociaux et environnementaux"], a:[0], e:"La méthode assume de ne <b>pas</b> être exhaustive&nbsp;: elle vise le <b>représentatif</b>. C'est cohérent avec le fondement qui impose de limiter le nombre de valeurs métier et de biens supports — chercher l'exhaustivité rendrait l'étude inexploitable."},
{id:"G03", ch:21, d:2, q:"Sur quoi la méthode EBIOS RM centre-t-elle l'analyse de risques&nbsp;?", o:["Sur les métiers","Sur les experts cyber","Sur les experts juridiques","Sur les biens supports techniques"], a:[0], e:"C'est le sens de l'<b>approche centrée métier</b>&nbsp;: on part de ce qui a de la valeur pour l'organisation, pas de la technique. Les experts cyber interviennent surtout à l'<b>atelier 4</b>."},
{id:"G04", ch:21, d:2, q:"Quand la méthode EBIOS RM produit-elle des résultats exploitables&nbsp;?", o:["À la sortie de chaque atelier","Exclusivement à l'issue des ateliers 1 et 5","Uniquement à la fin des cinq ateliers","Jamais avant la seconde itération"], a:[0], e:"Chaque atelier a ses propres livrables, utilisables seuls&nbsp;: le socle de sécurité après l'atelier 1, la cartographie de l'écosystème après le 3. C'est aussi ce qui rend l'<b>approche Flash</b> défendable."},
{id:"G05", ch:21, d:1, q:"Par qui la méthode EBIOS est-elle maintenue&nbsp;?", o:["Par l'ANSSI, avec le soutien du Club EBIOS","Par l'ANSSI seule","Par le Club EBIOS seul","Par l'ISO, via le comité de l'ISO 27005"], a:[0], e:"Les deux acteurs, pas l'un ou l'autre. Le <b>Club EBIOS</b> est une association d'utilisateurs et d'experts&nbsp;; c'est aussi lui qui porte le <b>référentiel de compétences</b> sur lequel s'appuie la formation."},
{id:"G06", ch:21, d:3, q:"Quelles sont les <b>quatre valeurs</b> de la méthode EBIOS RM&nbsp;?", o:["Concrète · Efficiente · Convaincante · Collaborative","Cohérente · Efficace · Complète · Coercitive","Complète · Communicante · Contextuelle · Coconstruite","Claire · Exhaustive · Conforme · Contrôlée"], a:[0], e:"Quatre mots en <b>C-E-C-C</b>. Repère utile pour éliminer&nbsp;: «&nbsp;<b>complète</b>&nbsp;» ne peut pas en faire partie, ce serait contradictoire avec une méthode qui ne retient que les risques <b>les plus représentatifs</b>."},
{id:"G07", ch:21, d:2, q:"Quelle est la différence entre EBIOS RM et l'ISO 27005&nbsp;?", o:["L'ISO 27005 est une norme, EBIOS RM une méthode","EBIOS RM est une norme, l'ISO 27005 une méthode","Ce sont deux méthodes concurrentes","EBIOS RM est un sous-ensemble de l'ISO 27005"], a:[0], e:"La norme dit <b>quoi</b> faire, la méthode dit <b>comment</b>. EBIOS RM est <b>conforme</b> à l'ISO 27005 sans en être un sous-ensemble — et l'ISO 27005, contrairement à l'ISO 27001, <b>n'est pas certifiable</b>."},
{id:"G08", ch:27, d:2, q:"Que ne permet pas de faire un outil comme Agile Risk Manager&nbsp;?", o:["Être certifié ISO 27005","Conduire les cinq ateliers de la méthode","Produire des exports Word, Excel et PDF","Travailler à plusieurs sur la même étude"], a:[0], e:"L'outil est <b>labellisé ANSSI</b> et gère toute la méthode, mais aucun outil ne délivre de certification — et l'<b>ISO 27005 n'est pas une norme certifiable</b> de toute façon. La norme certifiable du domaine, c'est l'<b>ISO 27001</b>."},
{id:"G09", ch:21, d:2, q:"Comment les cinq ateliers doivent-ils être abordés&nbsp;?", o:["Ils sont tous utiles, mais à sélectionner en fonction du contexte","Les cinq sont obligatoires dans tous les cas","Seuls les ateliers 1 et 5 sont réellement utiles","L'ordre n'a pas d'importance"], a:[0], e:"C'est le fondement qui autorise l'<b>approche Flash</b>&nbsp;: conduire les ateliers 1 et 5 seuls quand la structure ou le temps l'imposent. Ce n'est pas un raccourci honteux, c'est un choix de profondeur — à condition de l'assumer."},
{id:"G10", ch:22, d:2, q:"Que représente une <b>mission</b> dans l'atelier 1&nbsp;?", o:["La finalité, la raison d'être de l'objet de l'étude, en termes métier","La liste des tâches confiées à l'équipe d'analyse","Le périmètre technique du système étudié","L'objectif de conformité réglementaire visé"], a:[0], e:"La mission se formule <b>en termes métier</b>, pas techniques&nbsp;: «&nbsp;distribuer des contenus sous licence par abonnement&nbsp;», pas «&nbsp;exploiter une plateforme cloud&nbsp;». Les <b>valeurs métier</b> se rattachent ensuite à elle."},
{id:"G11", ch:22, d:2, q:"Comment les valeurs métier sont-elles choisies&nbsp;?", o:["En fonction de leur valeur réelle et concrète pour l'organisation","En reprenant la liste des applications du système d'information","En retenant tout ce qui figure au registre des traitements","Par ordre de coût de remplacement"], a:[0], e:"Et il y en a peu&nbsp;: le fondement impose d'en <b>limiter le nombre</b>. Une valeur métier est un <b>processus ou une information</b> — jamais une application ni un serveur, qui sont des biens supports."},
{id:"G12", ch:25, d:3, q:"De quelles manières la vraisemblance des scénarios opérationnels peut-elle être calculée&nbsp;?", o:["Expresse, standard, avancée","Rapide, standard, complexe","Standard, complexe, rapide","Simple, pondérée, probabiliste"], a:[0], e:"<b>Expresse</b>&nbsp;: une évaluation globale du scénario, sans détail par action. <b>Standard</b>&nbsp;: la vraisemblance de chaque action élémentaire. <b>Avancée</b>&nbsp;: pour chaque action, la <b>difficulté technique</b> et la <b>probabilité de succès</b>. La progression va du scénario à l'action, puis de l'action à ses composantes."},
{id:"G13", ch:25, d:2, q:"Autour de quoi les scénarios opérationnels sont-ils construits&nbsp;?", o:["D'une Cyber Kill Chain","D'une chaîne d'événements redoutés","D'une suite d'événements intermédiaires","De la matrice des risques"], a:[0], e:"La séquence <b>connaître → rentrer → trouver → exploiter</b> est une kill chain simplifiée. Le référentiel à citer si on vous demande sur quoi s'appuyer pour détailler les modes opératoires&nbsp;: <b>MITRE ATT&amp;CK</b>."},
{id:"G14", ch:26, d:3, q:"Lequel de ces éléments <b>n'alimente pas</b> la construction du PACS&nbsp;?", o:["Les risques résiduels","Les mesures issues de l'atelier 3 sur l'écosystème","La stratégie de traitement du risque","Les écarts au socle de sécurité"], a:[0], e:"Les risques résiduels sont le <b>résultat</b> du PACS, pas son entrée&nbsp;: on bâtit le plan, <b>puis</b> on réévalue ce qui reste. Confondre l'entrée et la sortie est le piège classique de l'atelier 5."},
{id:"G15", ch:26, d:2, q:"Quelles sont les options principales de traitement d'un risque&nbsp;?", o:["Réduire, accepter, refuser, partager","Réduire, ignorer, déléguer, assurer","Éviter, corriger, surveiller, documenter","Accepter, corriger, escalader, clore"], a:[0], e:"Le guide ANSSI emploie une autre formulation pour les mêmes options&nbsp;: <b>réduire · maintenir · refuser · transférer</b>. <b>Accepter = maintenir</b>, <b>partager = transférer</b>. Sachez lire les deux vocabulaires."},
{id:"G16", ch:26, d:3, q:"Laquelle de ces caractéristiques est <b>absente</b> du choix d'une mesure de sécurité dans un PACS&nbsp;?", o:["Les parties prenantes","Le responsable de la mesure","L'échéance de mise en œuvre","Le coût ou la difficulté de mise en œuvre"], a:[0], e:"Les parties prenantes appartiennent à la <b>cartographie de l'écosystème</b> (atelier 3), pas au plan d'action. Une mesure du PACS porte un intitulé, un responsable, une échéance, un coût et les <b>risques qu'elle traite</b>."},
{id:"G17", ch:26, d:2, q:"Une fois le PACS construit, que fait-on&nbsp;?", o:["On évalue le risque résiduel et on itère l'analyse le cas échéant","On clôt l'étude et on archive les livrables","On transmet le plan au prestataire et on passe à autre chose","On recote la gravité des événements redoutés"], a:[0], e:"La gravité ne se recote <b>pas</b>&nbsp;: les mesures agissent sur la <b>vraisemblance</b>, pas sur ce que l'organisation a à perdre. Et l'itération est constitutive de la méthode — d'où le <b>cadre de suivi</b> et le <b>comité de pilotage</b>."},
{id:"G18", ch:24, d:2, q:"Que signifie le fait qu'une partie prenante ait un <b>niveau de menace élevé</b>&nbsp;?", o:["C'est un vecteur d'attaque potentiel, à exploiter dans la construction des scénarios stratégiques","Qu'elle est malveillante et doit être écartée du périmètre","Que son contrat doit être résilié","Qu'elle constitue à elle seule un risque à traiter"], a:[0], e:"Un niveau de menace élevé ne dit rien des intentions de la partie prenante&nbsp;: il dit qu'<b>on dépend d'elle, qu'elle pénètre loin, et qu'elle n'est ni mûre ni auditée</b>. Elle devient un <b>chemin</b> possible, ce qui appelle des mesures — souvent contractuelles."}

];
